async fn create_child_job(
    state: &AppState,
    session: &SessionDetail,
    parent_job_id: &str,
    parent_worker: &WorkerSummary,
    proposal: ChildJobProposal,
    target_plan: ChildJobTargetPlan,
    images: &[SessionTurnImage],
) -> Result<String> {
    let limits = child_job_limits_for_lane(&target_plan.lane);
    create_child_job_with_limits(
        state,
        session,
        parent_job_id,
        parent_worker,
        proposal,
        target_plan,
        limits,
        images,
    )
    .await
}

#[derive(Debug, Clone, Copy)]
struct ChildJobRunLimits {
    max_steps: usize,
    max_tool_calls: usize,
    max_wall_clock_secs: u64,
}

#[derive(Debug, Clone)]
struct ChildJobTargetPlan {
    lane: String,
    target: HiddenWorkerTarget,
}

async fn resolve_child_job_target_plan(
    state: &AppState,
    session: &SessionSummary,
    proposal: &ChildJobProposal,
    needs_vision_tools: bool,
) -> Result<ChildJobTargetPlan> {
    let requested_route_id = proposal
        .route_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty());

    if let Some(route_id) = requested_route_id {
        if route_id == ACTION_EXECUTOR_LANE {
            let target = resolve_hidden_worker_target_with_route_override(
                state,
                session,
                ACTION_EXECUTOR_LANE,
                needs_vision_tools,
                None,
            )
            .await
            .map_err(|error| anyhow!("worker_action.invalid: {}", error.message))?;
            return Ok(ChildJobTargetPlan {
                lane: ACTION_EXECUTOR_LANE.to_string(),
                target,
            });
        }

        let mut route_session = session.clone();
        route_session.route_id = route_id.to_string();
        route_session.route_title = String::new();
        route_session.provider = String::new();
        route_session.model = String::new();
        route_session.provider_base_url = String::new();
        route_session.provider_api_key = String::new();
        let target = resolve_hidden_worker_target_with_route_override(
            state,
            &route_session,
            MAIN_EXECUTOR_LANE,
            needs_vision_tools,
            Some(route_id),
        )
        .await
        .map_err(|error| anyhow!("worker_action.invalid: {}", error.message))?;
        ensure_child_main_target_supports_images(&target, needs_vision_tools, Some(route_id))?;
        return Ok(ChildJobTargetPlan {
            lane: MAIN_EXECUTOR_LANE.to_string(),
            target,
        });
    }

    let target = resolve_hidden_worker_target_with_route_override(
        state,
        session,
        MAIN_EXECUTOR_LANE,
        needs_vision_tools,
        None,
    )
    .await
    .map_err(|error| {
        anyhow!(
            "worker_action.invalid: default main child route is unavailable: {}. Configure a runnable main model or set route_id=\"utility\" for a read-only utility child check; no automatic fallback was used.",
            error.message
        )
    })?;
    ensure_child_main_target_supports_images(&target, needs_vision_tools, None)?;
    Ok(ChildJobTargetPlan {
        lane: MAIN_EXECUTOR_LANE.to_string(),
        target,
    })
}

fn ensure_child_main_target_supports_images(
    target: &HiddenWorkerTarget,
    needs_vision_tools: bool,
    route_id: Option<&str>,
) -> Result<()> {
    if !needs_vision_tools || target_supports_vision_with_tools(target) {
        return Ok(());
    }
    let route_label = route_id
        .map(|id| format!("main child route '{id}'"))
        .unwrap_or_else(|| "default main child route".to_string());
    Err(anyhow!(
        "worker_action.invalid: {route_label} is unavailable for image-bearing delegation: selected provider '{}' does not support vision with tools. Configure a vision-capable main model or set route_id=\"utility\" for a read-only utility child check; no automatic fallback was used.",
        target.provider
    ))
}

async fn create_child_job_with_limits(
    state: &AppState,
    session: &SessionDetail,
    parent_job_id: &str,
    parent_worker: &WorkerSummary,
    proposal: ChildJobProposal,
    target_plan: ChildJobTargetPlan,
    limits: ChildJobRunLimits,
    images: &[SessionTurnImage],
) -> Result<String> {
    let title = proposal.title.trim();
    if title.is_empty() {
        bail!("child job titles must not be empty");
    }
    let prompt = proposal.prompt.trim();
    if prompt.is_empty() {
        bail!("child job prompts must not be empty");
    }
    let effective_task_class = effective_child_task_class(&proposal);
    let delegation_key = child_delegation_key(&proposal);
    let parent_generation =
        parent_delegation_generation(&state.store.get_job(parent_job_id)?, &BTreeSet::new());
    // `working_dir` is per-child and scope-checked here. It is not a lock:
    // parents that spawn write-capable siblings should pass a dedicated
    // worktree path for each child.
    let working_dir = if let Some(value) = proposal.working_dir.as_deref() {
        resolve_scoped_path_in_roots(
            parent_worker,
            value,
            &parent_worker.read_roots,
            false,
            "read",
        )?
    } else {
        PathBuf::from(&parent_worker.working_dir)
    };
    let read_roots = if proposal.working_dir.is_some() {
        vec![working_dir.display().to_string()]
    } else {
        parent_worker.read_roots.clone()
    };
    let write_roots = child_worker_write_roots(
        parent_worker,
        &target_plan.lane,
        &working_dir,
        proposal.working_dir.is_some(),
    )?;

    let child_job_id = Uuid::new_v4().to_string();
    let child_worker_id = Uuid::new_v4().to_string();
    let child_job = state.store.create_job(JobRecord {
        id: child_job_id.clone(),
        session_id: Some(session.session.id.clone()),
        parent_job_id: Some(parent_job_id.to_string()),
        template_id: None,
        task_class: effective_task_class.clone(),
        title: format!("Child {}", title),
        purpose: title.to_string(),
        trigger_kind: "child_job".to_string(),
        state: "queued".to_string(),
        requested_by: "agent".to_string(),
        prompt_excerpt: excerpt(prompt, 160),
        publication_intent_text: Some(prompt.to_string()),
    })?;
    let child_working_dir = working_dir.display().to_string();
    if child_job.publication_requested {
        record_publication_git_hygiene_baseline(state, &child_job, &child_working_dir)?;
    }
    state.store.create_worker(WorkerRecord {
        id: child_worker_id.clone(),
        job_id: child_job_id.clone(),
        parent_worker_id: Some(parent_worker.id.clone()),
        title: format!("Child {} worker: {}", target_plan.lane, title),
        lane: target_plan.lane.clone(),
        state: "queued".to_string(),
        provider: target_plan.target.provider,
        model: target_plan.target.model,
        route_id: target_plan.target.route_id,
        route_title: target_plan.target.route_title,
        provider_base_url: target_plan.target.provider_base_url,
        provider_api_key: target_plan.target.provider_api_key,
        provider_session_id: String::new(),
        working_dir: child_working_dir,
        read_roots,
        write_roots,
        max_steps: limits.max_steps,
        max_tool_calls: limits.max_tool_calls,
        max_wall_clock_secs: limits.max_wall_clock_secs,
    })?;
    state.store.update_job(
        &child_job_id,
        JobPatch {
            root_worker_id: Some(child_worker_id.clone()),
            metadata_json: Some(json!({
                "child_contract": effective_task_class.clone().unwrap_or_default(),
                "delegation_key": delegation_key,
                "parent_generation": parent_generation,
            })),
            ..JobPatch::default()
        },
    )?;
    // Per-child route selection controls model/provider/transport and the
    // bounded child capability set. Approval policy is still applied when a
    // child proposes any mutating or command action.
    state.store.replace_tool_capability_grants(
        &child_worker_id,
        &child_worker_capabilities_for_lane(parent_worker, &target_plan.lane),
    )?;
    let child_worker = state
        .store
        .get_job(&child_job_id)?
        .workers
        .into_iter()
        .find(|item| item.id == child_worker_id)
        .ok_or_else(|| {
            anyhow!(
                "Child worker '{}' was not found after creation",
                child_worker_id
            )
        })?;

    let checkpoint = WorkerCheckpoint {
        session_id: session.session.id.clone(),
        prompt_text: prompt.to_string(),
        images: images.to_vec(),
        conversation: vec![CheckpointMessage {
            role: "system".to_string(),
            content: worker_system_prompt(&child_worker),
            images: Vec::new(),
            compacted: false,
            compacted_range: None,
        }],
        next_prompt: None,
        pending_action: None,
        browser_verification_final_answer_rejected: false,
        patch_loop_guardrail_triggered: false,
    };
    state.store.write_worker_checkpoint(
        &child_worker.id,
        &serde_json::to_value(checkpoint).context("failed to encode child worker checkpoint")?,
    )?;

    publish_job_created(state, &child_job).await;
    publish_worker_updated(state, &child_worker).await;
    publish_job_updated(state, &state.store.get_job(parent_job_id)?.job).await;
    spawn_job_task(state.clone(), child_job_id.clone());
    Ok(child_job_id)
}

fn build_child_job_results_prompt(summary: &str, results: &[Value]) -> String {
    format!(
        "Child job results are ready.\nReason for the fan-out: {}\nStructured results:\n{}\n\
Return one JSON action for the next step. If the work is done, return final_answer with a complete user-facing answer.",
        summary,
        serde_json::to_string_pretty(results)
            .unwrap_or_else(|_| Value::Array(results.to_vec()).to_string())
    )
}

fn child_job_join_outcome(detail: &JobDetail) -> &'static str {
    if detail.job.state == "completed" && detail.job.completion_status == "satisfied" {
        return CHILD_OUTCOME_SUCCEEDED;
    }
    if detail.job.state == "canceled" {
        return CHILD_OUTCOME_CANCELED;
    }
    if detail.job.completion_status == "blocked" || detail.job.state == "failed" {
        return CHILD_OUTCOME_BLOCKED_TERMINAL;
    }
    CHILD_OUTCOME_BLOCKED_RECOVERABLE
}

fn child_job_join_outcome_json(detail: &JobDetail) -> Value {
    json!({
        "job_id": detail.job.id,
        "title": detail.job.title,
        "task_class": detail.job.task_class,
        "state": detail.job.state,
        "completion_status": detail.job.completion_status,
        "completion_blockers": detail.job.completion_blockers,
        "join_outcome": child_job_join_outcome(detail),
    })
}

fn child_job_join_outcomes_json(child_details: &[JobDetail]) -> Vec<Value> {
    child_details
        .iter()
        .map(child_job_join_outcome_json)
        .collect::<Vec<_>>()
}

fn is_single_successful_delegated_child_join(
    worker: &WorkerSummary,
    child_details: &[JobDetail],
) -> bool {
    worker.parent_worker_id.is_none()
        && child_details.len() == 1
        && child_details[0].job.task_class.as_deref() == Some(DELEGATED_SUBTASK_TASK_CLASS)
        && child_job_join_outcome(&child_details[0]) == CHILD_OUTCOME_SUCCEEDED
}

fn child_join_final_answer(detail: &JobDetail) -> String {
    let report = child_job_full_report_text(detail);
    if !report.trim().is_empty() {
        return report.trim().to_string();
    }
    if !detail.job.result_summary.trim().is_empty() {
        return detail.job.result_summary.trim().to_string();
    }
    format!("{} completed successfully.", detail.job.title)
}

fn child_join_final_summary(detail: &JobDetail) -> String {
    if !detail.job.result_summary.trim().is_empty() {
        format!(
            "Joined delegated child: {}",
            detail.job.result_summary.trim()
        )
    } else {
        format!("Joined delegated child {}", detail.job.title)
    }
}

async fn complete_parent_from_successful_delegated_child_join(
    state: &AppState,
    session: &SessionDetail,
    job_id: &str,
    worker: &mut WorkerSummary,
    step_count: usize,
    tool_call_count: usize,
    join_summary: &str,
    child_detail: &JobDetail,
    child_outcomes: &[Value],
) -> Result<()> {
    let summary = child_join_final_summary(child_detail);
    let final_answer = child_join_final_answer(child_detail);
    let metadata = json!({
        "daemon_child_join": {
            "join_summary": join_summary,
            "join_kind": "single_successful_delegated_child",
            "required_outcome": CHILD_OUTCOME_SUCCEEDED,
            "child_outcomes": child_outcomes,
        }
    });
    complete_job_with_final_answer(
        state,
        session,
        job_id,
        worker,
        step_count,
        tool_call_count,
        &summary,
        &final_answer,
        &metadata,
        &[],
    )
    .await
}

fn is_pending_child_job_action(pending: &PendingToolAction) -> bool {
    pending.action_kind == "child_jobs" || !pending.child_job_ids.is_empty()
}

fn worker_wall_clock_exceeded(worker: &WorkerSummary, now: i64) -> bool {
    worker.max_wall_clock_secs > 0
        && now.saturating_sub(worker.created_at) >= worker.max_wall_clock_secs as i64
}

fn wait_audit_data(wait: &WorkerWaitRecord) -> Value {
    json!({
        "wait_id": wait.id,
        "summary": excerpt(&wait.summary, 240),
        "until": &wait.until,
        "max_wait_seconds": wait.max_wait_seconds,
        "started_at": wait.started_at,
    })
}

fn wait_status_text(wait: &WorkerWaitRecord, now: i64) -> String {
    let waited = now.saturating_sub(wait.started_at).max(0);
    format!(
        "waiting until {} (woke in {})",
        wait_condition_label(&wait.until),
        format_duration(wait_remaining_seconds(wait, now).unwrap_or(0).max(0) as u64)
            .unwrap_or_else(|| "0s".to_string())
    )
    .replace(
        "(woke in 0s)",
        &format!(
            "(waiting for {} elapsed)",
            format_duration(waited as u64).unwrap_or_else(|| "0s".to_string())
        ),
    )
}

fn wait_condition_label(until: &WaitUntil) -> String {
    match until {
        WaitUntil::DelaySeconds { delay_seconds } => {
            format!(
                "delay of {}",
                format_duration(*delay_seconds).unwrap_or_else(|| format!("{delay_seconds}s"))
            )
        }
        WaitUntil::AbsoluteUnix { absolute_unix } => {
            format!("unix time {absolute_unix}")
        }
        WaitUntil::AuditEvent {
            event_kind,
            target_pattern,
            status,
        } => {
            let mut parts = vec![format!("audit event '{event_kind}'")];
            if let Some(target_pattern) =
                target_pattern.as_deref().filter(|value| !value.is_empty())
            {
                parts.push(format!("target matching '{target_pattern}'"));
            }
            if let Some(status) = status.as_deref().filter(|value| !value.is_empty()) {
                parts.push(format!("status '{status}'"));
            }
            parts.join(", ")
        }
        WaitUntil::ChildJobsCompleted { job_ids } => {
            format!("{} child job(s) complete", job_ids.len())
        }
        WaitUntil::ArtifactKind {
            job_id,
            artifact_kind,
        } => {
            format!("artifact kind '{artifact_kind}' on job {job_id}")
        }
    }
}

fn reusable_child_rank(state: &str) -> Option<u8> {
    match state {
        "completed" => Some(0),
        "queued" | "running" | "paused" | "waiting" => Some(1),
        "blocked" | "failed" => Some(2),
        _ => None,
    }
}

fn parent_delegation_generation(detail: &JobDetail, exclude_child_ids: &BTreeSet<String>) -> usize {
    let parent_tool_changes = detail
        .tool_calls
        .iter()
        .filter(|call| {
            matches!(
                call.status.as_str(),
                "completed" | "failed" | "denied" | "canceled"
            )
        })
        .count();
    let sibling_terminal_changes = detail
        .child_jobs
        .iter()
        .filter(|child| {
            !exclude_child_ids.contains(&child.id) && is_terminal_job_state(&child.state)
        })
        .count();
    parent_tool_changes + sibling_terminal_changes
}

async fn reuse_equivalent_child_jobs_if_any(
    state: &AppState,
    session: &SessionDetail,
    job_id: &str,
    worker: &mut WorkerSummary,
    checkpoint: &mut WorkerCheckpoint,
    step: &mut usize,
    tool_calls: usize,
    summary: &str,
    jobs: &[ChildJobProposal],
) -> Result<Option<LoopDisposition>> {
    let requested_keys = jobs.iter().map(child_delegation_key).collect::<Vec<_>>();
    if requested_keys.is_empty() {
        return Ok(None);
    }
    let parent = state.store.get_job(job_id)?;
    let requested_key_set = requested_keys.iter().cloned().collect::<BTreeSet<_>>();
    let mut candidates_by_key = BTreeMap::<String, Vec<(u64, u8, i64, String)>>::new();
    for child in &parent.child_jobs {
        let Some(key) = child
            .metadata_json
            .get("delegation_key")
            .and_then(Value::as_str)
        else {
            continue;
        };
        if !requested_key_set.contains(key) {
            continue;
        }
        let Some(rank) = reusable_child_rank(&child.state) else {
            continue;
        };
        let Some(parent_generation) = child
            .metadata_json
            .get("parent_generation")
            .and_then(Value::as_u64)
        else {
            continue;
        };
        candidates_by_key.entry(key.to_string()).or_default().push((
            parent_generation,
            rank,
            child.created_at,
            child.id.clone(),
        ));
    }
    if requested_keys
        .iter()
        .any(|key| !candidates_by_key.contains_key(key))
    {
        return Ok(None);
    }

    let candidate_generations = candidates_by_key
        .values()
        .flat_map(|candidates| candidates.iter().map(|(generation, _, _, _)| *generation))
        .collect::<BTreeSet<_>>();
    let mut best_match: Option<(u32, u64, Vec<String>)> = None;
    for generation in candidate_generations.iter().rev() {
        let mut generation_rank = 0u32;
        let mut matched_child_ids = Vec::with_capacity(requested_keys.len());
        for key in &requested_keys {
            let Some((_, rank, _, child_id)) = candidates_by_key.get(key).and_then(|candidates| {
                candidates
                    .iter()
                    .filter(|(candidate_generation, _, _, _)| candidate_generation == generation)
                    .min_by_key(|(_, rank, created_at, child_id)| {
                        (*rank, *created_at, child_id.as_str())
                    })
            }) else {
                matched_child_ids.clear();
                break;
            };
            generation_rank = generation_rank.saturating_add(*rank as u32);
            matched_child_ids.push(child_id.clone());
        }
        if matched_child_ids.len() != requested_keys.len() {
            continue;
        }
        matched_child_ids.sort();
        matched_child_ids.dedup();
        let matched_child_id_set = matched_child_ids.iter().cloned().collect::<BTreeSet<_>>();
        let current_generation = parent_delegation_generation(&parent, &matched_child_id_set);
        if current_generation as u64 != *generation {
            continue;
        }
        let replace = best_match
            .as_ref()
            .is_none_or(|(best_rank, best_generation, _)| {
                generation_rank < *best_rank
                    || (generation_rank == *best_rank && *generation > *best_generation)
            });
        if replace {
            best_match = Some((generation_rank, *generation, matched_child_ids));
        }
    }
    let Some((_, _, matched_child_ids)) = best_match else {
        return Ok(None);
    };
    let child_details = matched_child_ids
        .iter()
        .map(|child_job_id| state.store.get_job(child_job_id))
        .collect::<Result<Vec<_>>>()?;
    let all_terminal = child_details
        .iter()
        .all(|detail| is_terminal_job_state(&detail.job.state));
    let completed_count = child_details
        .iter()
        .filter(|detail| detail.job.state == "completed")
        .count();
    let child_outcomes = child_job_join_outcomes_json(&child_details);
    let daemon_completion_join =
        all_terminal && is_single_successful_delegated_child_join(worker, &child_details);

    *step += 1;
    *worker = state.store.update_worker(
        &worker.id,
        WorkerPatch {
            state: Some("running".to_string()),
            step_count: Some(*step),
            last_error: Some(String::new()),
            ..WorkerPatch::default()
        },
    )?;

    if all_terminal {
        let reuse_summary = if completed_count == child_details.len() {
            format!("Reusing equivalent child job result for: {summary}")
        } else {
            format!(
                "Equivalent child job already ended without success for: {summary}. Do not spawn a duplicate; surface the blocker or choose a distinct recovery."
            )
        };
        let results = child_details
            .iter()
            .map(child_job_result_json)
            .collect::<Result<Vec<_>>>()?;
        checkpoint.pending_action = None;
        checkpoint.next_prompt = if daemon_completion_join {
            None
        } else {
            Some(build_child_job_results_prompt(&reuse_summary, &results))
        };
    } else {
        checkpoint.pending_action = Some(PendingToolAction {
            action_kind: "child_jobs".to_string(),
            tool_call_id: String::new(),
            approval_id: None,
            command_session_id: None,
            child_job_ids: matched_child_ids.clone(),
            summary: format!("Waiting for equivalent child job(s) already in flight: {summary}"),
            tool: String::new(),
            args: Value::Null,
        });
        checkpoint.next_prompt = None;
    }
    state.store.write_worker_checkpoint(
        &worker.id,
        &serde_json::to_value(&checkpoint).context("failed to encode worker checkpoint")?,
    )?;
    let _ = state.store.append_job_event(JobEventRecord {
        job_id: job_id.to_string(),
        worker_id: Some(worker.id.clone()),
        event_type: "child.jobs.reused".to_string(),
        status: if all_terminal { "completed" } else { "running" }.to_string(),
        summary: format!("Reused {} equivalent child job(s)", matched_child_ids.len()),
        detail: if all_terminal {
            format!(
                "{} child job(s) completed and {} ended without success.",
                completed_count,
                child_details.len().saturating_sub(completed_count)
            )
        } else {
            "An equivalent child fan-out is already in flight.".to_string()
        },
        data_json: json!({
            "child_job_ids": matched_child_ids,
            "requested_keys": requested_keys,
            "child_outcomes": child_outcomes,
            "join_decision": {
                "daemon_completed_parent": daemon_completion_join,
                "required_outcome": CHILD_OUTCOME_SUCCEEDED,
                "join_kind": if daemon_completion_join { "single_successful_delegated_child" } else if all_terminal { "prompt_join" } else { "wait_for_in_flight" },
            },
        }),
    });
    if daemon_completion_join {
        complete_parent_from_successful_delegated_child_join(
            state,
            session,
            job_id,
            worker,
            *step,
            tool_calls,
            summary,
            &child_details[0],
            &child_outcomes,
        )
        .await?;
        return Ok(Some(LoopDisposition::Return));
    }
    publish_job_updated(state, &state.store.get_job(job_id)?.job).await;
    publish_worker_updated(state, worker).await;
    Ok(Some(LoopDisposition::Continue))
}

fn wait_remaining_seconds(wait: &WorkerWaitRecord, now: i64) -> Option<i64> {
    let condition_remaining = match &wait.until {
        WaitUntil::DelaySeconds { delay_seconds } => Some(
            wait.started_at
                .saturating_add(*delay_seconds as i64)
                .saturating_sub(now),
        ),
        WaitUntil::AbsoluteUnix { absolute_unix } => Some(absolute_unix.saturating_sub(now)),
        WaitUntil::AuditEvent { .. }
        | WaitUntil::ChildJobsCompleted { .. }
        | WaitUntil::ArtifactKind { .. } => None,
    };
    let cap_remaining = wait.max_wait_seconds.map(|max_wait_seconds| {
        wait.started_at
            .saturating_add(max_wait_seconds as i64)
            .saturating_sub(now)
    });

    match (condition_remaining, cap_remaining) {
        (Some(condition), Some(cap)) => Some(condition.min(cap)),
        (Some(condition), None) => Some(condition),
        (None, Some(cap)) => Some(cap),
        (None, None) => None,
    }
}

fn format_duration(seconds: u64) -> Option<String> {
    if seconds == 0 {
        return Some("0s".to_string());
    }
    let hours = seconds / 3600;
    let minutes = (seconds % 3600) / 60;
    let secs = seconds % 60;
    if hours > 0 {
        Some(format!("{hours}h {minutes}m"))
    } else if minutes > 0 {
        Some(format!("{minutes}m {secs}s"))
    } else {
        Some(format!("{secs}s"))
    }
}

fn child_job_result_json(detail: &JobDetail) -> Result<Value> {
    let report = child_job_report_preview_text(detail);
    Ok(json!({
        "job_id": detail.job.id,
        "title": detail.job.title,
        "state": detail.job.state,
        "completion_status": detail.job.completion_status,
        "completion_blockers": detail.job.completion_blockers,
        "join_outcome": child_job_join_outcome(detail),
        "purpose": detail.job.purpose,
        "result_summary": detail.job.result_summary,
        "last_error": detail.job.last_error,
        "worker_count": detail.job.worker_count,
        "report": report,
        "outcome": {
            "publication_requested": detail.job.publication_requested,
            "publication_status": detail.job.publication_status,
            "publication_summary": detail.job.publication_summary,
            "pr_url": detail.job.pr_url,
            "source_branch": detail.job.source_branch,
            "target_branch": detail.job.target_branch,
            "validation_status": detail.job.validation_status,
            "browser_verification_required": detail.job.browser_verification_required,
            "browser_verification_status": detail.job.browser_verification_status,
            "browser_verification_summary": detail.job.browser_verification_summary,
            "browser_verification_artifact_ids": detail.job.browser_verification_artifact_ids,
            "cleanup_status": detail.job.cleanup_status,
            "cleanup_paths": detail.job.cleanup_paths,
        },
        "artifact_count": detail.job.artifact_count,
        "command_session_count": detail.command_sessions.len(),
        "tool_call_count": detail.tool_calls.len(),
        "worker_notes": detail
            .workers
            .iter()
            .map(|worker| json!({
                "id": worker.id,
                "title": worker.title,
                "state": worker.state,
                "working_dir": worker.working_dir,
                "last_error": worker.last_error,
            }))
            .collect::<Vec<_>>(),
        "events": detail
            .events
            .iter()
            .rev()
            .take(4)
            .map(|event| json!({
                "event_type": event.event_type,
                "status": event.status,
                "summary": event.summary,
                "detail": event.detail,
                "data_json": event.data_json,
            }))
            .collect::<Vec<_>>(),
        "report_path": detail
            .artifacts
            .iter()
            .find(|artifact| artifact.kind == "child-report")
            .map(|artifact| artifact.path.clone())
            .unwrap_or_default(),
    }))
}

fn child_job_report_preview_text(detail: &JobDetail) -> String {
    detail
        .artifacts
        .iter()
        .find(|artifact| artifact.kind == "child-report")
        .map(|artifact| artifact.preview_text.clone())
        .unwrap_or_default()
}

fn child_job_full_report_text(detail: &JobDetail) -> String {
    let Some(artifact) = detail
        .artifacts
        .iter()
        .find(|artifact| artifact.kind == "child-report")
    else {
        return String::new();
    };
    fs::read_to_string(&artifact.path).unwrap_or_else(|_| artifact.preview_text.clone())
}

async fn complete_job_with_final_answer(
    state: &AppState,
    session: &SessionDetail,
    job_id: &str,
    worker: &mut WorkerSummary,
    step_count: usize,
    tool_call_count: usize,
    summary: &str,
    final_answer: &str,
    final_answer_metadata: &Value,
    final_answer_artifacts: &[FinalAnswerArtifact],
) -> Result<()> {
    let detail = state.store.get_job(job_id)?;
    let mut publication_patch = publication_outcome_patch_with_metadata(
        &detail.job,
        summary,
        final_answer,
        final_answer_metadata,
        step_count,
        tool_call_count,
    );
    apply_publication_temp_hygiene(
        &detail,
        &session.session.working_dir,
        &mut publication_patch,
    );
    if detail.job.browser_verification_required
        && matches!(
            detail.job.browser_verification_status.as_str(),
            "pending" | "not_performed"
        )
    {
        let summary = if detail.job.browser_verification_artifact_ids.is_empty() {
            "Browser verification was not performed before completion.".to_string()
        } else {
            "Browser evidence was captured, but no verification outcome was asserted before completion."
                .to_string()
        };
        let _ = state.store.update_job(
            job_id,
            JobPatch {
                browser_verification_status: Some("not_performed".to_string()),
                browser_verification_summary: Some(summary.clone()),
                ..JobPatch::default()
            },
        );
        let _ = state.store.append_job_event(JobEventRecord {
            job_id: job_id.to_string(),
            worker_id: Some(worker.id.clone()),
            event_type: "job.browser_verification.completed".to_string(),
            status: "not_performed".to_string(),
            summary: "Completed, not browser-verified".to_string(),
            detail: summary,
            data_json: json!({ "reason": "completion_without_verification" }),
        });
    }

    let completion_job_result =
        record_context_integrity_detection(state, &session.session, job_id, Some(final_answer))
            .await;
    state
        .agent
        .terminate_job_command_sessions(
            job_id,
            "The job completed and closed any remaining Nucleus-owned command sessions.",
            "closed",
        )
        .await;
    let completion_job = completion_job_result?;
    reconcile_publication_browser_status_with_completion(&completion_job, &mut publication_patch);
    let projected_blocker = projected_completion_gate_blocker(&completion_job, &publication_patch);
    let terminal_job_state = if projected_blocker.is_some() {
        "blocked"
    } else {
        "completed"
    };
    let visible_final_answer = contradiction_checked_final_answer(
        final_answer,
        terminal_job_state,
        &publication_patch,
        projected_blocker.as_deref(),
    );

    let mut visible_turn_id = None;
    let mut report_artifact = None;
    let mut structured_artifacts = Vec::new();
    for artifact in final_answer_artifacts {
        let artifact = write_job_artifact(
            state,
            job_id,
            Some(&worker.id),
            None,
            text_artifact_with_metadata(
                &artifact.kind,
                artifact.title.clone(),
                "md",
                "text/markdown",
                artifact.content.clone(),
                artifact.metadata.clone(),
            ),
        )?;
        structured_artifacts.push(artifact);
    }
    let mut post_turn_memory_outcomes: Vec<MemoryOutcome> = Vec::new();
    if detail.job.parent_job_id.is_none() {
        let final_turn_id = Uuid::new_v4().to_string();
        state.store.append_session_turn(
            &session.session.id,
            &final_turn_id,
            "assistant",
            &visible_final_answer,
            &[],
        )?;
        post_turn_memory_outcomes = crate::extract_memory_decisions_after_turn(
            state,
            &session.session.id,
            Some(&final_turn_id),
        )
        .await;
        visible_turn_id = Some(final_turn_id);
        state.store.update_session(
            &session.session.id,
            SessionPatch {
                state: Some("active".to_string()),
                last_error: Some(String::new()),
                ..SessionPatch::default()
            },
        )?;
    } else {
        let artifact = write_job_artifact(
            state,
            job_id,
            Some(&worker.id),
            None,
            text_artifact(
                "child-report",
                format!("{} report", detail.job.title),
                "md",
                "text/markdown",
                visible_final_answer.clone(),
            ),
        )?;
        report_artifact = Some(artifact);
    }

    state.store.update_job(
        job_id,
        JobPatch {
            state: Some(terminal_job_state.to_string()),
            visible_turn_id,
            result_summary: Some(summary.to_string()),
            last_error: Some(String::new()),
            publication_requested: publication_patch.publication_requested,
            publication_status: publication_patch.publication_status.clone(),
            publication_summary: publication_patch.publication_summary.clone(),
            pr_url: publication_patch.pr_url.clone(),
            source_branch: publication_patch.source_branch.clone(),
            target_branch: publication_patch.target_branch.clone(),
            validation_status: publication_patch.validation_status.clone(),
            browser_verification_status: publication_patch.browser_verification_status.clone(),
            cleanup_status: publication_patch.cleanup_status.clone(),
            cleanup_paths: publication_patch.cleanup_paths.clone(),
            ..JobPatch::default()
        },
    )?;
    *worker = state.store.update_worker(
        &worker.id,
        WorkerPatch {
            state: Some("completed".to_string()),
            step_count: Some(step_count),
            tool_call_count: Some(tool_call_count),
            last_error: Some(String::new()),
            ..WorkerPatch::default()
        },
    )?;
    let mut terminal_metadata = final_answer_terminal_metadata(
        summary,
        &visible_final_answer,
        final_answer_metadata,
        &structured_artifacts,
        step_count,
        tool_call_count,
        &publication_patch,
    );
    if terminal_job_state == "blocked" {
        terminal_metadata["terminal_status"] = Value::String("blocked".to_string());
        terminal_metadata["blocked"] = Value::Bool(true);
    } else {
        terminal_metadata["terminal_status"] = Value::String("completed".to_string());
        terminal_metadata["blocked"] = Value::Bool(false);
    }
    let terminal_status = terminal_job_state.to_string();
    let _ = state.store.append_job_event(JobEventRecord {
        job_id: job_id.to_string(),
        worker_id: Some(worker.id.clone()),
        event_type: if terminal_status == "blocked" {
            "job.blocked".to_string()
        } else {
            "job.completed".to_string()
        },
        status: terminal_status,
        summary: summary.to_string(),
        detail: excerpt(&visible_final_answer, 320),
        data_json: terminal_metadata,
    });
    if let Some(publication_status) = publication_patch.publication_status.as_deref() {
        if publication_patch.publication_requested.unwrap_or(false) {
            let blocked = matches!(publication_status, "blocked" | "not_opened" | "failed");
            let _ = state.store.append_job_event(JobEventRecord {
                job_id: job_id.to_string(),
                worker_id: Some(worker.id.clone()),
                event_type: if blocked {
                    "job.publication.blocked".to_string()
                } else {
                    "job.publication.completed".to_string()
                },
                status: publication_status.to_string(),
                summary: publication_patch
                    .publication_summary
                    .clone()
                    .unwrap_or_else(|| summary.to_string()),
                detail: excerpt(&visible_final_answer, 320),
                data_json: json!({
                    "publication_requested": publication_patch.publication_requested.unwrap_or(true),
                    "publication_status": publication_status,
                    "pr_url": publication_patch.pr_url.clone().unwrap_or_default(),
                    "source_branch": publication_patch.source_branch.clone().unwrap_or_default(),
                    "target_branch": publication_patch.target_branch.clone().unwrap_or_default(),
                    "validation_status": publication_patch.validation_status.clone().unwrap_or_default(),
                    "browser_verification_status": publication_patch.browser_verification_status.clone().unwrap_or_default(),
                    "cleanup_status": publication_patch.cleanup_status.clone().unwrap_or_default(),
                    "cleanup_paths": publication_patch.cleanup_paths.clone().unwrap_or_default(),
                }),
            });
            if publication_patch.cleanup_status.as_deref() == Some("cleanup_required") {
                let cleanup_paths = publication_patch.cleanup_paths.clone().unwrap_or_default();
                let _ = state.store.append_job_event(JobEventRecord {
                    job_id: job_id.to_string(),
                    worker_id: Some(worker.id.clone()),
                    event_type: "job.publication.cleanup_required".to_string(),
                    status: "cleanup_required".to_string(),
                    summary: "Publication job left repo-local temp artifacts".to_string(),
                    detail: if cleanup_paths.is_empty() {
                        "Nucleus marked cleanup as required for this publication job.".to_string()
                    } else {
                        format!(
                            "New repo-local temp paths were detected after job start: {}",
                            cleanup_paths.join(", ")
                        )
                    },
                    data_json: json!({
                        "cleanup_status": "cleanup_required",
                        "cleanup_paths": cleanup_paths,
                    }),
                });
            }
        }
    }
    let _ = try_record_audit_event(
        state,
        AuditEventRecord {
            kind: if terminal_job_state == "blocked" {
                "session.job.blocked".to_string()
            } else {
                "session.job.completed".to_string()
            },
            target: format!("job:{job_id}"),
            status: if terminal_job_state == "blocked" {
                "warning".to_string()
            } else {
                "success".to_string()
            },
            summary: if terminal_job_state == "blocked" {
                format!(
                    "Blocked Utility Worker job for session '{}'.",
                    session.session.title
                )
            } else {
                format!(
                    "Completed Utility Worker job for session '{}'.",
                    session.session.title
                )
            },
            detail: format!(
                "session_id={} provider={} model={} steps={} tool_calls={}",
                session.session.id, worker.provider, worker.model, step_count, tool_call_count
            ),
        },
    )
    .await;

    if detail.job.parent_job_id.is_none() {
        if let Ok(updated) = state.store.get_session(&session.session.id) {
            let _ = publish_session_event(state, updated).await;
        }
        let (prompt_status, prompt_label, prompt_detail) =
            terminal_prompt_status_copy(terminal_job_state);
        publish_prompt_status(
            state,
            &session.session,
            worker,
            prompt_status,
            prompt_label,
            prompt_detail,
            &post_turn_memory_outcomes,
        )
        .await;
    } else {
        if let Some(artifact) = report_artifact.as_ref() {
            publish_artifact_added(state, artifact).await;
        }
        for artifact in &structured_artifacts {
            publish_artifact_added(state, artifact).await;
        }
        if let Some(parent_job_id) = detail.job.parent_job_id.as_deref() {
            publish_job_updated(state, &state.store.get_job(parent_job_id)?.job).await;
        }
    }
    if detail.job.parent_job_id.is_none() {
        for artifact in &structured_artifacts {
            publish_artifact_added(state, artifact).await;
        }
    }

    publish_terminal_job_event(state, &state.store.get_job(job_id)?.job).await;
    publish_worker_updated(state, worker).await;
    let _ = publish_overview_event(state).await;
    Ok(())
}

async fn complete_job_with_budget_checkpoint(
    state: &AppState,
    session: &SessionDetail,
    job_id: &str,
    worker: &mut WorkerSummary,
    checkpoint: &WorkerCheckpoint,
    step_count: usize,
    tool_call_count: usize,
    budget_kind: &str,
) -> Result<()> {
    let summary = format!("Reached current {budget_kind} budget");
    let latest_progress_detail = state
        .store
        .get_job(job_id)
        .ok()
        .and_then(|detail| latest_worker_progress_detail(&detail, &worker.id));
    let final_answer = build_budget_checkpoint_answer(
        session,
        worker,
        checkpoint,
        latest_progress_detail.as_deref(),
        step_count,
        tool_call_count,
        budget_kind,
    );
    let metadata = json!({});
    complete_job_with_final_answer(
        state,
        session,
        job_id,
        worker,
        step_count,
        tool_call_count,
        &summary,
        &final_answer,
        &metadata,
        &[],
    )
    .await
}

fn build_budget_checkpoint_answer(
    session: &SessionDetail,
    worker: &WorkerSummary,
    checkpoint: &WorkerCheckpoint,
    latest_progress_detail: Option<&str>,
    step_count: usize,
    tool_call_count: usize,
    budget_kind: &str,
) -> String {
    let limit = match budget_kind {
        "action" => worker.max_tool_calls,
        "wall-clock" => worker.max_wall_clock_secs as usize,
        _ => worker.max_steps,
    };
    let latest_checkpoint = checkpoint
        .next_prompt
        .as_deref()
        .or(latest_progress_detail)
        .or_else(|| {
            checkpoint
                .conversation
                .iter()
                .rev()
                .find(|message| message.role == "user")
                .map(|message| message.content.as_str())
        })
        .map(|value| excerpt(value, 1_200))
        .filter(|value| !value.trim().is_empty())
        .unwrap_or_else(|| "No checkpoint detail was available.".to_string());
    let pending = checkpoint
        .pending_action
        .as_ref()
        .map(|action| {
            format!(
                "\n\nPending action: {} ({})",
                action.tool,
                excerpt(&action.summary, 240)
            )
        })
        .unwrap_or_default();
    let project = if session.session.working_dir.is_empty() {
        "the current workspace".to_string()
    } else {
        session.session.working_dir.clone()
    };

    format!(
        "Nucleus reached the current {budget_kind} budget for this run ({step_count} steps, {tool_call_count} actions, limit {limit}) while working in {project}.\n\nLatest checkpoint:\n{latest_checkpoint}{pending}\n\nSend a follow-up such as \"continue from the checkpoint\" to give Nucleus a fresh run budget without losing the visible session context."
    )
}

fn latest_worker_progress_detail(detail: &JobDetail, worker_id: &str) -> Option<String> {
    detail
        .events
        .iter()
        .rev()
        .find(|event| {
            event.event_type == "worker.progress" && event.worker_id.as_deref() == Some(worker_id)
        })
        .map(|event| event.detail.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn build_initial_step_prompt(
    session: &SessionSummary,
    prompt: &str,
    worker: &WorkerSummary,
    low_context_turn: bool,
) -> String {
    let next_action_instruction = if worker.parent_worker_id.is_none() && !low_context_turn {
        "Return one JSON action for the next step. For broad or multi-step repo/workspace inspection, multi-file analysis, implementation, debugging, deep reasoning, or anything likely to need more than about 1-2 evidence/tool calls, return spawn_child_jobs first unless delegation is concretely impossible. Use tool_call only for trivial single-step inspection, targeted triage, validation, or a specific final join gap. If you need to persist a non-terminal checkpoint, return progress_update. Only return final_answer when it is a complete terminal response, never an action plan, progress update, or a description of what should happen next."
    } else {
        "Return one JSON action for the next step. If repo or workspace inspection is needed, return a tool_call. If you need to persist a non-terminal checkpoint, return progress_update. Only return final_answer when it is a complete terminal response, never an action plan, progress update, or a description of what should happen next."
    };
    let project_context = if session.projects.is_empty() {
        format!(
            "No project is attached. Working directory: {}",
            session.working_dir
        )
    } else {
        format!(
            "Primary working directory: {}\nAttached projects:\n{}",
            session.working_dir,
            session
                .projects
                .iter()
                .map(|project| format!("- {} ({})", project.title, project.absolute_path))
                .collect::<Vec<_>>()
                .join("\n")
        )
    };
    format!(
        "You are handling a Nucleus-owned session prompt.\n\
Session title: {}\n\
{}\n\
Visible provider: {} / {}\n\
Utility Worker provider: {} / {}\n\
Prompt-time context and user request:\n{}\n\
{}\n\
If the current user request corrects, refines, or challenges the previous answer, treat it as a continuation of the unresolved task. Do not merely acknowledge or restate the correction; use the visible conversation history to continue troubleshooting or answer the corrected question.\n\
If the current user asks why they still cannot see a previous UI/code change, mentions being on the wrong branch/worktree, or asks whether an update/release/instance mismatch explains what they see, first answer that deployment visibility question directly. Inspect git state, the active session worktree, and any managed-release install path as needed. Do not make another code edit unless the user explicitly asks for one after that diagnosis, and do not let Browser verification status replace the branch/worktree/release answer.",
        session.title,
        project_context,
        session.provider,
        if session.model.is_empty() {
            "default"
        } else {
            session.model.as_str()
        },
        worker.provider,
        if worker.model.is_empty() {
            "default"
        } else {
            worker.model.as_str()
        },
        prompt,
        next_action_instruction
    )
}

fn add_publication_initial_prompt_guidance(
    state: &AppState,
    job: &JobSummary,
    prompt: String,
) -> String {
    if !job.publication_requested {
        return prompt;
    }

    let job_tmp_dir = state
        .store
        .state_dir_path()
        .join("jobs")
        .join(&job.id)
        .join("tmp");
    let _ = fs::create_dir_all(&job_tmp_dir);
    format!(
        "{}\n\nPublication job requirements:\n\
- The user request is publication-oriented, so the final response JSON must include explicit terminal metadata for publication_status, validation_status, browser_verification_status, and cleanup_status. Put these as JSON fields, not prose labels inside the visible final_answer message.\n\
- Allowed publication_status values: not_requested, opened, merged, not_opened, blocked, failed.\n\
- Allowed validation_status values: passed, failed, not_performed, unavailable.\n\
- Allowed browser_verification_status values: not_required, pending, passed, failed, not_performed, unavailable.\n\
- Allowed cleanup_status values: clean, cleaned, cleanup_required, unknown.\n\
- Include pr_url, source_branch, and target_branch when known.\n\
- For protected target branches, resolve and merge the PR through the GitHub PR-merge path such as gh pr merge or the github.* tools. Do not push directly to a protected branch, for example git push <sha>:dev, or check out a shared local dev worktree; if branch protection blocks the merge, set publication_status=blocked or failed with the concrete reason.\n\
- If a requested PR merge succeeds, set publication_status=merged and record the merge result in publication_summary.\n\
- Use the daemon-owned Browser tools for rendered verification when possible. Do not create repo-local Playwright projects, .tmp-playwright, or ad-hoc .tmp-* verification folders.\n\
- Missing Browser or Playwright tooling is not a generic job failure. Record browser_verification_status=unavailable or not_performed with the concrete reason.\n\
- Put scratch verification scripts outside the git worktree when you need them. Scoped file tools can only write within worker write roots; use shell commands for daemon-owned scratch work in this job temp directory: {}\n\
- Before terminal final_answer, check for job-created .tmp-* leftovers in the repo. Clean only files this job created, or set cleanup_status=cleanup_required and list the paths.",
        prompt,
        job_tmp_dir.display()
    )
}

fn publication_job_temp_dir(state: &AppState, job_id: &str) -> PathBuf {
    state
        .store
        .state_dir_path()
        .join("jobs")
        .join(job_id)
        .join("tmp")
}

fn record_publication_git_hygiene_baseline(
    state: &AppState,
    job: &JobSummary,
    working_dir: &str,
) -> Result<()> {
    let job_tmp_dir = publication_job_temp_dir(state, &job.id);
    fs::create_dir_all(&job_tmp_dir)
        .with_context(|| format!("failed to create job temp dir '{}'", job_tmp_dir.display()))?;
    let temp_paths = collect_repo_temp_paths(working_dir);
    let _ = state.store.append_job_event(JobEventRecord {
        job_id: job.id.clone(),
        worker_id: None,
        event_type: "job.publication.git_baseline".to_string(),
        status: "captured".to_string(),
        summary: "Captured publication git hygiene baseline".to_string(),
        detail: if temp_paths.is_empty() {
            "No repo-local .tmp-* leftovers were present at job start.".to_string()
        } else {
            format!(
                "Repo-local temp paths present at job start: {}",
                temp_paths.join(", ")
            )
        },
        data_json: json!({
            "working_dir": working_dir,
            "job_tmp_dir": job_tmp_dir.display().to_string(),
            "temp_paths": temp_paths,
        }),
    });
    Ok(())
}

async fn record_context_integrity_detection(
    state: &AppState,
    session: &SessionSummary,
    job_id: &str,
    final_answer: Option<&str>,
) -> Result<JobSummary> {
    let detail = state.store.get_job(job_id)?;
    let current = detail.job;
    let mut patch = context_integrity_patch(state, session, &current);
    patch.command_session_cwd_evidence_json = Some(Some(
        serde_json::to_string(&command_session_cwd_evidence(
            session,
            &detail.command_sessions,
        ))
        .unwrap_or_else(|_| "{}".to_string()),
    ));
    patch.metadata_json = Some(context_integrity_metadata_with_session_state(
        state, session, &current, job_id,
    )?);
    if let Some(final_answer) = final_answer {
        patch.target_entity_evidence_json = Some(Some(
            serde_json::to_string(&target_entity_evidence(
                state,
                session,
                &current,
                &detail.command_sessions,
                final_answer,
            )?)
            .unwrap_or_else(|_| "{}".to_string()),
        ));
        patch.process_state_evidence_json = Some(Some(
            serde_json::to_string(
                &process_state_evidence(state, &detail.command_sessions, final_answer).await?,
            )
            .unwrap_or_else(|_| "{}".to_string()),
        ));
    }
    let updated = state.store.update_job(job_id, patch)?;
    let _ = state.store.append_job_event(JobEventRecord {
        job_id: job_id.to_string(),
        worker_id: None,
        event_type: "job.context_integrity.checked".to_string(),
        status: updated.completion_status.clone(),
        summary: context_integrity_event_summary(&updated),
        detail: context_integrity_event_detail(&updated),
        data_json: json!({
            "worktree_base_evidence": {
                "status": updated.worktree_base_status.clone(),
                "reason": updated.worktree_base_reason.clone(),
                "base_ref": updated.worktree_base_ref.clone(),
                "head_sha": updated.worktree_head_sha.clone(),
                "canonical_sha": updated.canonical_base_sha.clone(),
                "behind_by": updated.worktree_behind_by,
            },
            "branch_repo_evidence": {
                "status": updated.branch_repo_status.clone(),
                "reason": updated.branch_repo_reason.clone(),
                "observed_origin": updated.worktree_origin_url.clone(),
                "expected_origin": updated.expected_origin_url.clone(),
                "observed_branch": updated.observed_git_branch.clone(),
                "expected_branch": updated.expected_git_branch.clone(),
            },
            "cwd_evidence": updated.command_session_cwd_evidence_json.as_deref()
                .and_then(|value| serde_json::from_str::<Value>(value).ok())
                .unwrap_or_else(|| json!({})),
            "session_state_evidence": updated.metadata_json
                .get("session_state_evidence")
                .cloned()
                .unwrap_or_else(|| json!({})),
            "target_entity_evidence": updated.target_entity_evidence_json.as_deref()
                .and_then(|value| serde_json::from_str::<Value>(value).ok())
                .unwrap_or_else(|| json!({})),
            "process_state_evidence": updated.process_state_evidence_json.as_deref()
                .and_then(|value| serde_json::from_str::<Value>(value).ok())
                .unwrap_or_else(|| json!({})),
        }),
    });
    Ok(updated)
}

fn command_session_cwd_evidence(
    session: &SessionSummary,
    command_sessions: &[CommandSessionSummary],
) -> Value {
    let declared = session.working_dir.trim();
    if declared.is_empty() {
        return json!({
            "status": "satisfied",
            "reason": "session has no declared working_dir; cwd gate is trivially satisfied",
            "declared_working_dir": "",
            "observed_cwds": [],
            "offending_command_session_ids": [],
            "offending_cwds": [],
        });
    }
    if command_sessions.is_empty() {
        return json!({
            "status": "pending",
            "reason": "no command sessions recorded yet",
            "declared_working_dir": declared,
            "observed_cwds": [],
            "offending_command_session_ids": [],
            "offending_cwds": [],
        });
    }

    let mut observed = Vec::new();
    let mut offending_ids = Vec::new();
    let mut offending_cwds = Vec::new();
    let mut missing_ids = Vec::new();
    let mut unresolved = Vec::new();
    let mut stale_recorded_cwd_ids = Vec::new();
    for command_session in command_sessions {
        let cwd = command_session.cwd.trim();
        observed.push(json!({
            "command_session_id": command_session.id,
            "cwd": cwd,
            "state": command_session.state,
        }));
        if cwd.is_empty() {
            missing_ids.push(command_session.id.clone());
            continue;
        }
        match path_is_under_declared_root(Path::new(cwd), Path::new(declared)) {
            Ok(true) => {}
            Ok(false) => {
                offending_ids.push(command_session.id.clone());
                offending_cwds.push(cwd.to_string());
            }
            Err(error) => {
                match lexical_path_is_under_declared_root(Path::new(cwd), Path::new(declared)) {
                    Some(true) if command_session.state == "completed" => {
                        stale_recorded_cwd_ids.push(command_session.id.clone());
                    }
                    Some(true) => unresolved.push(format!("{}: {error}", command_session.id)),
                    Some(false) => {
                        offending_ids.push(command_session.id.clone());
                        offending_cwds.push(cwd.to_string());
                    }
                    None => unresolved.push(format!("{}: {error}", command_session.id)),
                }
            }
        }
    }

    if !offending_ids.is_empty() {
        return json!({
            "status": "blocked",
            "reason": "one or more command sessions ran outside the declared working_dir",
            "declared_working_dir": declared,
            "observed_cwds": observed,
            "offending_command_session_ids": offending_ids,
            "offending_cwds": offending_cwds,
        });
    }
    if !missing_ids.is_empty() {
        return json!({
            "status": "pending",
            "reason": format!("cwd not recorded for command session(s): {}", missing_ids.join(", ")),
            "declared_working_dir": declared,
            "observed_cwds": observed,
            "offending_command_session_ids": [],
            "offending_cwds": [],
        });
    }
    if !unresolved.is_empty() {
        return json!({
            "status": "pending",
            "reason": format!("could not resolve command session cwd(s): {}", unresolved.join("; ")),
            "declared_working_dir": declared,
            "observed_cwds": observed,
            "offending_command_session_ids": [],
            "offending_cwds": [],
        });
    }

    json!({
        "status": "satisfied",
        "reason": if stale_recorded_cwd_ids.is_empty() {
            String::new()
        } else {
            format!("recorded cwd no longer exists for completed command session(s), but the recorded path remains under the declared working_dir: {}", stale_recorded_cwd_ids.join(", "))
        },
        "declared_working_dir": declared,
        "observed_cwds": observed,
        "offending_command_session_ids": [],
        "offending_cwds": [],
        "stale_recorded_cwd_ids": stale_recorded_cwd_ids,
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ContextClaim {
    claim_text: String,
    entity_type: String,
    identifier: String,
    action: String,
}

fn target_entity_evidence(
    state: &AppState,
    session: &SessionSummary,
    job: &JobSummary,
    command_sessions: &[CommandSessionSummary],
    final_answer: &str,
) -> Result<Value> {
    let claims = extract_target_entity_claims(final_answer);
    if claims.is_empty() {
        return Ok(json!({
            "status": "satisfied",
            "reason": "no extractable target-entity claims; gate is trivially satisfied",
            "claims": [],
        }));
    }

    let audit_events = state
        .store
        .list_audit_events_since(job.created_at.saturating_sub(1))?
        .into_iter()
        .filter(|event| audit_event_matches_job(event, job))
        .collect::<Vec<_>>();
    let mut verified = Vec::new();
    for claim in claims {
        let result = match claim.entity_type.as_str() {
            "branch" => verify_branch_claim(session, command_sessions, &claim),
            "file" => verify_file_claim(session, job.created_at, &claim),
            "external_entity" => verify_external_entity_claim(&audit_events, &claim),
            _ => json!({
                "status": "pending",
                "reason": "unsupported claim type",
                "daemon_evidence_searched": "none",
            }),
        };
        verified.push(claim_result_json(&claim, result));
    }

    Ok(evidence_rollup(
        verified,
        "all extractable target-entity claims match daemon evidence",
        "one or more target-entity claims have no daemon evidence",
        "target-entity evidence is still pending",
    ))
}

async fn process_state_evidence(
    state: &AppState,
    command_sessions: &[CommandSessionSummary],
    final_answer: &str,
) -> Result<Value> {
    let claims = extract_process_state_claims(final_answer);
    if claims.is_empty() {
        return Ok(json!({
            "status": "satisfied",
            "reason": "no extractable process or port claims; gate is trivially satisfied",
            "claims": [],
        }));
    }

    let browser_observation = if claims
        .iter()
        .any(|claim| claim.entity_type == "browser_sidecar")
    {
        Some(state.browser.observe_sidecar().await.map_err(|error| {
            json!({
                "status": "pending",
                "reason": format!("browser observation failed: {error}"),
                "daemon_evidence_searched": "browser sidecar process handle",
            })
        }))
    } else {
        None
    };
    let mut verified = Vec::new();
    for claim in claims {
        let result = match claim.entity_type.as_str() {
            "browser_sidecar" => match &browser_observation {
                Some(Ok(observation)) => verify_browser_claim(observation, &claim),
                Some(Err(error_result)) => error_result.clone(),
                None => verify_browser_claim(&None, &claim),
            },
            "command_session" => verify_command_success_claim(command_sessions, &claim),
            "port" => verify_port_claim(command_sessions, &claim),
            _ => json!({
                "status": "pending",
                "reason": "unsupported process claim type",
                "daemon_evidence_searched": "none",
            }),
        };
        verified.push(claim_result_json(&claim, result));
    }

    Ok(evidence_rollup(
        verified,
        "all extractable process and port claims match daemon observations",
        "one or more process or port claims contradict daemon observations",
        "process or port evidence is still pending",
    ))
}

fn claim_result_json(claim: &ContextClaim, result: Value) -> Value {
    json!({
        "claim_text": claim.claim_text,
        "entity_type": claim.entity_type,
        "identifier": claim.identifier,
        "action": claim.action,
        "result": result.get("status").and_then(Value::as_str).unwrap_or("pending"),
        "reason": result.get("reason").and_then(Value::as_str).unwrap_or_default(),
        "daemon_evidence_searched": result
            .get("daemon_evidence_searched")
            .and_then(Value::as_str)
            .unwrap_or_default(),
        "last_observed_state": result
            .get("last_observed_state")
            .and_then(Value::as_str)
            .unwrap_or_default(),
        "observation_timestamp": result
            .get("observation_timestamp")
            .and_then(Value::as_i64),
        "matched": result.get("matched").and_then(Value::as_bool).unwrap_or(false),
    })
}

fn evidence_rollup(
    claims: Vec<Value>,
    satisfied_reason: &str,
    blocked_reason: &str,
    pending_reason: &str,
) -> Value {
    let has_blocked = claims
        .iter()
        .any(|claim| claim.get("result").and_then(Value::as_str) == Some("blocked"));
    let has_pending = claims
        .iter()
        .any(|claim| claim.get("result").and_then(Value::as_str) == Some("pending"));
    let (status, reason) = if has_blocked {
        ("blocked", blocked_reason)
    } else if has_pending {
        ("pending", pending_reason)
    } else {
        ("satisfied", satisfied_reason)
    };
    json!({
        "status": status,
        "reason": reason,
        "claims": claims,
    })
}

fn extract_target_entity_claims(final_answer: &str) -> Vec<ContextClaim> {
    let mut claims = Vec::new();
    for sentence in claim_sentences(final_answer) {
        let lower = sentence.to_ascii_lowercase();
        if let Some(claim) = extract_branch_claim(&sentence, &lower) {
            claims.push(claim);
        }
        for phrase in ["created file ", "modified file ", "updated file "] {
            if let Some(path) = token_after_phrase(&sentence, phrase) {
                claims.push(ContextClaim {
                    claim_text: sentence.clone(),
                    entity_type: "file".to_string(),
                    identifier: path,
                    action: phrase.trim().replace(' ', "_"),
                });
            }
        }
        if contains_any(
            &lower,
            &["opened", "created", "published", "referenced", "closed"],
        ) {
            for (marker, entity) in [
                ("pr #", "pr"),
                ("pull request #", "pr"),
                ("issue #", "issue"),
            ] {
                for (number, marker_start, number_end) in
                    number_mentions_after_marker(&lower, marker)
                {
                    claims.push(ContextClaim {
                        claim_text: sentence.clone(),
                        entity_type: "external_entity".to_string(),
                        identifier: format!("{entity}#{number}"),
                        action: external_action_near(&lower, marker_start, number_end),
                    });
                }
            }
        }
    }
    dedupe_claims(claims)
}

fn extract_process_state_claims(final_answer: &str) -> Vec<ContextClaim> {
    let mut claims = Vec::new();
    for sentence in claim_sentences(final_answer) {
        let lower = sentence.to_ascii_lowercase();
        if lower.contains("browser")
            && contains_any(&lower, &["ready", "healthy", "running", "available"])
            && !is_negated_browser_health_claim(&lower)
        {
            claims.push(ContextClaim {
                claim_text: sentence.clone(),
                entity_type: "browser_sidecar".to_string(),
                identifier: "browser_sidecar".to_string(),
                action: "healthy".to_string(),
            });
        }
        if is_process_success_claim(&lower) {
            claims.push(ContextClaim {
                claim_text: sentence.clone(),
                entity_type: "command_session".to_string(),
                identifier: command_claim_identifier(&lower),
                action: "succeeded".to_string(),
            });
        }
        if lower.contains("port ")
            && contains_any(
                &lower,
                &["ready", "healthy", "running", "listening", "available"],
            )
            && !is_negated_port_health_claim(&lower)
        {
            if let Some(port) = number_after_marker(&lower, "port ") {
                claims.push(ContextClaim {
                    claim_text: sentence.clone(),
                    entity_type: "port".to_string(),
                    identifier: port,
                    action: "healthy".to_string(),
                });
            }
        }
    }
    dedupe_claims(claims)
}

fn claim_sentences(text: &str) -> Vec<String> {
    text.lines()
        .flat_map(|line| line.split([';', '!', '?']))
        .flat_map(|item| item.split(". "))
        .map(|item| {
            item.trim()
                .trim_start_matches(['-', '*', ' '])
                .trim()
                .to_string()
        })
        .filter(|item| !item.is_empty())
        .collect()
}

fn contains_any(text: &str, needles: &[&str]) -> bool {
    needles.iter().any(|needle| text.contains(needle))
}

fn is_process_success_claim(lower: &str) -> bool {
    contains_any(
        lower,
        &[
            "tests passed",
            "test passed",
            "tests succeeded",
            "test succeeded",
            "command succeeded",
            "command passed",
            "cargo test passed",
            "npm test passed",
            "npm run check passed",
        ],
    ) || ((lower.contains("tests showed") || lower.contains("test showed"))
        && contains_any(lower, &["pass", "passing", "succeed", "success"]))
}

fn command_session_text(command: &str, args: &[String]) -> String {
    std::iter::once(command)
        .chain(args.iter().map(String::as_str))
        .collect::<Vec<_>>()
        .join(" ")
        .to_ascii_lowercase()
}

fn is_validation_command(text: &str) -> bool {
    contains_any(
        text,
        &[
            "cargo test",
            "cargo nextest",
            "npm test",
            "npm run test",
            "npm run check",
            "npm run build",
            "pnpm test",
            "pnpm check",
            "pnpm build",
            "bun test",
            "bun run test",
            "bun run check",
            "bun run build",
            "node --test",
        ],
    )
}

fn dedupe_claims(claims: Vec<ContextClaim>) -> Vec<ContextClaim> {
    let mut seen = BTreeSet::new();
    claims
        .into_iter()
        .filter(|claim| {
            seen.insert(format!(
                "{}:{}:{}",
                claim.entity_type, claim.identifier, claim.claim_text
            ))
        })
        .collect()
}

fn token_after_phrase(sentence: &str, phrase: &str) -> Option<String> {
    let lower = sentence.to_ascii_lowercase();
    let start = lower.find(phrase)? + phrase.len();
    sanitize_claim_token(sentence.get(start..)?.trim())
}

fn sanitize_claim_token(value: &str) -> Option<String> {
    let trimmed = value.trim();
    if trimmed.is_empty() {
        return None;
    }
    let token = if let Some(quote) = trimmed
        .chars()
        .next()
        .filter(|c| matches!(c, '`' | '"' | '\''))
    {
        let rest = trimmed.get(quote.len_utf8()..).unwrap_or_default();
        rest.find(quote)
            .and_then(|end| rest.get(..end))
            .unwrap_or(rest)
            .to_string()
    } else {
        trimmed
            .split_whitespace()
            .next()
            .unwrap_or_default()
            .to_string()
    };
    let token = token
        .trim_start_matches(|c: char| {
            matches!(c, '`' | '"' | '\'' | ',' | ':' | ')' | '(' | '[' | ']')
        })
        .trim_end_matches(|c: char| {
            matches!(
                c,
                '`' | '"' | '\'' | ',' | ':' | '.' | ')' | '(' | '[' | ']'
            )
        })
        .to_string();
    (!token.is_empty()).then_some(token)
}

fn number_after_marker(text: &str, marker: &str) -> Option<String> {
    numbers_after_marker(text, marker).into_iter().next()
}

fn numbers_after_marker(text: &str, marker: &str) -> Vec<String> {
    number_mentions_after_marker(text, marker)
        .into_iter()
        .map(|(number, _, _)| number)
        .collect()
}

fn number_mentions_after_marker(text: &str, marker: &str) -> Vec<(String, usize, usize)> {
    let mut numbers = Vec::new();
    let mut offset = 0;
    while let Some(relative_start) = text.get(offset..).and_then(|rest| rest.find(marker)) {
        let marker_start = offset + relative_start;
        let number_start = marker_start + marker.len();
        let Some(rest) = text.get(number_start..) else {
            break;
        };
        let number = rest
            .chars()
            .take_while(|c| c.is_ascii_digit())
            .collect::<String>();
        let advance = marker.len() + number.len().max(1);
        if !number.is_empty() {
            let number_end = number_start + number.len();
            numbers.push((number, marker_start, number_end));
        }
        offset += relative_start + advance;
    }
    numbers
}

fn extract_branch_claim(sentence: &str, lower: &str) -> Option<ContextClaim> {
    for (phrase, action) in [
        ("created branch ", "created"),
        ("merged branch ", "merged"),
        ("checked out branch ", "checked_out"),
        ("switched to branch ", "checked_out"),
        ("switched branch to ", "checked_out"),
        ("switched branch ", "checked_out"),
    ] {
        if let Some(branch) = token_after_phrase(sentence, phrase) {
            return Some(ContextClaim {
                claim_text: sentence.to_string(),
                entity_type: "branch".to_string(),
                identifier: branch,
                action: action.to_string(),
            });
        }
    }

    let branch = token_after_phrase(sentence, "branch ")?;
    let branch_lower = branch.to_ascii_lowercase();
    for (suffix, action) in [
        ("created", "created"),
        ("merged", "merged"),
        ("checked out", "checked_out"),
        ("switched", "checked_out"),
    ] {
        if lower.contains(&format!("branch {branch_lower} {suffix}")) {
            return Some(ContextClaim {
                claim_text: sentence.to_string(),
                entity_type: "branch".to_string(),
                identifier: branch,
                action: action.to_string(),
            });
        }
    }
    None
}

fn is_negated_browser_health_claim(lower: &str) -> bool {
    contains_any(
        lower,
        &[
            "not ready",
            "not healthy",
            "not running",
            "not available",
            "isn't ready",
            "isn't healthy",
            "isn't running",
            "isn't available",
            "unavailable",
            "unhealthy",
            "failed",
            "failure",
        ],
    )
}

fn is_negated_port_health_claim(lower: &str) -> bool {
    contains_any(
        lower,
        &[
            "not ready",
            "not healthy",
            "not running",
            "not listening",
            "not available",
            "isn't ready",
            "isn't healthy",
            "isn't running",
            "isn't listening",
            "isn't available",
            "unavailable",
            "unhealthy",
            "failed",
            "failure",
        ],
    )
}

fn external_action(lower: &str) -> String {
    for action in ["opened", "created", "published", "referenced", "closed"] {
        if lower.contains(action) {
            return action.to_string();
        }
    }
    "referenced".to_string()
}

fn external_action_near(lower: &str, marker_start: usize, number_end: usize) -> String {
    let actions = ["opened", "created", "published", "referenced", "closed"];
    let mut best: Option<(usize, &str)> = None;
    for action in actions {
        let mut offset = 0;
        while let Some(relative_start) = lower.get(offset..).and_then(|rest| rest.find(action)) {
            let action_start = offset + relative_start;
            let action_end = action_start + action.len();
            let distance = if action_end <= marker_start {
                marker_start - action_end
            } else {
                action_start.saturating_sub(number_end)
            };
            if best.map_or(true, |(best_distance, _)| distance < best_distance) {
                best = Some((distance, action));
            }
            offset = action_end;
        }
    }
    best.map(|(_, action)| action.to_string())
        .unwrap_or_else(|| external_action(lower))
}

fn command_claim_identifier(lower: &str) -> String {
    if lower.contains("cargo test") {
        "cargo test".to_string()
    } else if lower.contains("npm run check") {
        "npm run check".to_string()
    } else if lower.contains("npm test") {
        "npm test".to_string()
    } else if lower.contains("command succeeded") || lower.contains("command passed") {
        "command".to_string()
    } else {
        "test".to_string()
    }
}

fn verify_branch_claim(
    session: &SessionSummary,
    command_sessions: &[CommandSessionSummary],
    claim: &ContextClaim,
) -> Value {
    let Some(worktree_path) = declared_session_git_path(session) else {
        return json!({
            "status": "pending",
            "reason": "session has no declared git worktree path",
            "daemon_evidence_searched": "session worktree local refs and command_sessions",
        });
    };
    if successful_branch_command_mentions(command_sessions, claim) {
        return json!({
            "status": "satisfied",
            "reason": "daemon-recorded command session mentions the branch action",
            "daemon_evidence_searched": "command_sessions command/args",
            "matched": true,
        });
    }
    let branch_ref = format!("refs/heads/{}", claim.identifier);
    let branch_exists = git_status(
        &worktree_path,
        &["show-ref", "--verify", "--quiet", &branch_ref],
    )
    .is_ok();
    if claim.action == "checked_out"
        && observe_session_git_state(&worktree_path)
            .map(|state| state.git_branch == claim.identifier)
            .unwrap_or(false)
    {
        return json!({
            "status": "satisfied",
            "reason": "worktree HEAD is on the claimed branch",
            "daemon_evidence_searched": format!("git symbolic-ref --short HEAD plus command_sessions command/args for {}", claim.identifier),
            "matched": true,
        });
    }
    json!({
        "status": "blocked",
        "reason": if branch_exists {
            "branch found, but no daemon-recorded branch operation matched the claimed action"
        } else {
            "branch not found and no daemon-recorded branch operation matched the claim"
        },
        "daemon_evidence_searched": format!("local refs via git show-ref plus command_sessions for {}", claim.identifier),
    })
}

fn verify_file_claim(session: &SessionSummary, job_started_at: i64, claim: &ContextClaim) -> Value {
    let Some(root) = session_worktree_probe_path(session) else {
        return json!({
            "status": "pending",
            "reason": "session has no declared filesystem root",
            "daemon_evidence_searched": "session worktree_path, working_dir, git_root",
        });
    };
    let claimed_path = Path::new(&claim.identifier);
    if claimed_path
        .components()
        .any(|component| matches!(component, Component::ParentDir | Component::Prefix(_)))
    {
        return json!({
            "status": "blocked",
            "reason": "claimed file path escapes the session workspace",
            "daemon_evidence_searched": format!("session workspace root {}", root.display()),
        });
    }
    let path = if claimed_path.is_absolute() {
        claimed_path.to_path_buf()
    } else {
        root.join(claimed_path)
    };
    if !path.starts_with(&root) {
        return json!({
            "status": "blocked",
            "reason": "claimed file path escapes the session workspace",
            "daemon_evidence_searched": format!("session workspace root {}", root.display()),
        });
    }
    let metadata = match fs::metadata(&path) {
        Ok(metadata) => metadata,
        Err(error) if error.kind() == ErrorKind::NotFound => {
            return json!({
                "status": "blocked",
                "reason": "claimed file does not exist",
                "daemon_evidence_searched": format!("filesystem metadata for {}", path.display()),
            });
        }
        Err(error) => {
            return json!({
                "status": "pending",
                "reason": format!("filesystem check failed: {error}"),
                "daemon_evidence_searched": format!("filesystem metadata for {}", path.display()),
            });
        }
    };
    if !metadata.is_file() {
        return json!({
            "status": "blocked",
            "reason": "claimed file path is not a regular file",
            "daemon_evidence_searched": format!("filesystem metadata for {}", path.display()),
        });
    }
    let modified_at = metadata
        .modified()
        .ok()
        .and_then(|mtime| mtime.duration_since(UNIX_EPOCH).ok())
        .map(|duration| duration.as_secs() as i64);
    if modified_at.is_some_and(|mtime| mtime >= job_started_at) {
        json!({
            "status": "satisfied",
            "reason": "claimed file exists and was modified during or after the job start",
            "daemon_evidence_searched": format!("filesystem metadata for {}", path.display()),
            "matched": true,
            "observation_timestamp": modified_at,
        })
    } else {
        json!({
            "status": "blocked",
            "reason": "claimed file exists but mtime is older than the job start",
            "daemon_evidence_searched": format!("filesystem metadata for {}", path.display()),
            "observation_timestamp": modified_at,
        })
    }
}

fn verify_external_entity_claim(
    audit_events: &[nucleus_protocol::AuditEvent],
    claim: &ContextClaim,
) -> Value {
    let matched = audit_events.iter().any(|event| {
        let haystack = format!(
            "{} {} {} {}",
            event.kind, event.target, event.summary, event.detail
        )
        .to_ascii_lowercase();
        event.status == "success"
            && external_entity_id_matches(&haystack, &claim.identifier)
            && external_audit_action_matches(&haystack, &claim.action)
    });
    if matched {
        json!({
            "status": "satisfied",
            "reason": "matching daemon audit event recorded",
            "daemon_evidence_searched": "current job audit_events kind/target/summary/detail since job start",
            "matched": true,
        })
    } else {
        json!({
            "status": "blocked",
            "reason": "claim references external entity with no daemon evidence",
            "daemon_evidence_searched": "current job audit_events kind/target/summary/detail since job start",
        })
    }
}

fn external_audit_action_matches(haystack: &str, action: &str) -> bool {
    match action {
        "referenced" => contains_any(haystack, &["referenced", "reference"]),
        "created" => contains_any(haystack, &["created", "opened", "published"]),
        "opened" => haystack.contains("opened"),
        "published" => haystack.contains("published"),
        "closed" => haystack.contains("closed"),
        _ => haystack.contains(action),
    }
}

fn external_entity_id_matches(haystack: &str, identifier: &str) -> bool {
    let Some((entity_type, number)) = identifier.split_once('#') else {
        return false;
    };
    let spaced = format!("{entity_type} #{number}");
    let compact = format!("{entity_type}#{number}");
    if contains_entity_id_token(haystack, &spaced) || contains_entity_id_token(haystack, &compact) {
        return true;
    }
    entity_type == "pr" && contains_entity_id_token(haystack, &format!("pull request #{number}"))
}

fn contains_entity_id_token(haystack: &str, needle: &str) -> bool {
    haystack.match_indices(needle).any(|(index, _)| {
        let before = haystack[..index].chars().next_back();
        let after = haystack[index + needle.len()..].chars().next();
        before.is_none_or(|ch| !ch.is_ascii_alphanumeric() && ch != '#')
            && after.is_none_or(|ch| !ch.is_ascii_alphanumeric())
    })
}

fn verify_browser_claim(
    observation: &Option<crate::browser::BrowserSidecarObservation>,
    _claim: &ContextClaim,
) -> Value {
    let Some(observation) = observation else {
        return json!({
            "status": "pending",
            "reason": "no observation recorded",
            "daemon_evidence_searched": "browser sidecar process handle",
        });
    };
    if observation.state == "running" {
        json!({
            "status": "satisfied",
            "reason": "browser sidecar process is running",
            "daemon_evidence_searched": "browser sidecar process handle",
            "last_observed_state": observation.state,
            "observation_timestamp": observation.observed_at,
            "matched": true,
        })
    } else {
        json!({
            "status": "blocked",
            "reason": "worker claimed Browser ready but daemon observation is not running",
            "daemon_evidence_searched": "browser sidecar process handle",
            "last_observed_state": observation.state,
            "observation_timestamp": observation.observed_at,
        })
    }
}

fn verify_command_success_claim(
    command_sessions: &[CommandSessionSummary],
    claim: &ContextClaim,
) -> Value {
    let identifier = claim.identifier.to_ascii_lowercase();
    let mut matching = command_sessions
        .iter()
        .filter(|command_session| command_claim_matches_session(&identifier, command_session))
        .collect::<Vec<_>>();
    matching.sort_by_key(|command_session| {
        (
            command_session
                .completed_at
                .unwrap_or(command_session.updated_at),
            command_session.updated_at,
            command_session.created_at,
        )
    });
    let Some(command_session) = matching.pop() else {
        return json!({
            "status": "pending",
            "reason": "no observation recorded",
            "daemon_evidence_searched": format!("command_sessions matching {identifier}"),
        });
    };
    let observed = format!(
        "state={} exit_code={}",
        command_session.state,
        command_session
            .exit_code
            .map(|code| code.to_string())
            .unwrap_or_else(|| "unknown".to_string())
    );
    if command_session.state == "completed" && command_session.exit_code == Some(0) {
        json!({
            "status": "satisfied",
            "reason": format!("matching command session {} succeeded", command_session.id),
            "daemon_evidence_searched": format!("command_sessions matching {identifier}"),
            "last_observed_state": observed,
            "observation_timestamp": command_session.completed_at.or(Some(command_session.updated_at)),
            "matched": true,
        })
    } else {
        json!({
            "status": "blocked",
            "reason": format!("matching command session {} did not succeed", command_session.id),
            "daemon_evidence_searched": format!("command_sessions matching {identifier}"),
            "last_observed_state": observed,
            "observation_timestamp": command_session.completed_at.or(Some(command_session.updated_at)),
        })
    }
}

fn verify_port_claim(command_sessions: &[CommandSessionSummary], claim: &ContextClaim) -> Value {
    let Ok(port) = claim.identifier.parse::<u16>() else {
        return json!({
            "status": "pending",
            "reason": "port claim is not a valid u16",
            "daemon_evidence_searched": format!("command_sessions with recorded port {}", claim.identifier),
        });
    };
    let mut matching = command_sessions
        .iter()
        .filter(|command_session| command_session.port == Some(port))
        .collect::<Vec<_>>();
    matching.sort_by_key(|command_session| {
        (
            command_session
                .completed_at
                .unwrap_or(command_session.updated_at),
            command_session.updated_at,
            command_session.created_at,
        )
    });
    let Some(command_session) = matching.pop() else {
        return json!({
            "status": "pending",
            "reason": "no observation recorded",
            "daemon_evidence_searched": format!("command_sessions with recorded port {}", claim.identifier),
        });
    };
    let observed = format!(
        "state={} exit_code={}",
        command_session.state,
        command_session
            .exit_code
            .map(|code| code.to_string())
            .unwrap_or_else(|| "unknown".to_string())
    );
    if command_session.state == "running"
        || (command_session.state == "completed" && command_session.exit_code == Some(0))
    {
        json!({
            "status": "satisfied",
            "reason": format!(
                "matching command session {} recorded port {}",
                command_session.id, claim.identifier
            ),
            "daemon_evidence_searched": format!("command_sessions with recorded port {}", claim.identifier),
            "last_observed_state": observed,
            "observation_timestamp": command_session.completed_at.or(Some(command_session.updated_at)),
            "matched": true,
        })
    } else {
        json!({
            "status": "blocked",
            "reason": format!(
                "matching command session {} for port {} is not healthy",
                command_session.id, claim.identifier
            ),
            "daemon_evidence_searched": format!("command_sessions with recorded port {}", claim.identifier),
            "last_observed_state": observed,
            "observation_timestamp": command_session.completed_at.or(Some(command_session.updated_at)),
        })
    }
}

fn command_claim_matches_session(
    identifier: &str,
    command_session: &CommandSessionSummary,
) -> bool {
    let text = command_session_text(&command_session.command, &command_session.args);
    let tokens = command_session_tokens(&command_session.command, &command_session.args);
    if identifier == "command" {
        return !text.trim().is_empty();
    }
    if identifier == "test" {
        return is_validation_command(&text)
            && tokens
                .iter()
                .any(|token| command_claim_token_matches("test", token));
    }
    identifier.split_whitespace().all(|token| {
        tokens
            .iter()
            .any(|candidate| command_claim_token_matches(token, candidate))
    })
}

fn command_claim_token_matches(required: &str, candidate: &str) -> bool {
    candidate == required
        || candidate
            .strip_prefix(required)
            .is_some_and(|suffix| suffix.starts_with(':'))
}

fn audit_event_matches_job(event: &nucleus_protocol::AuditEvent, job: &JobSummary) -> bool {
    let job_target = format!("job:{}", job.id);
    if event.target == job_target {
        return true;
    }
    let job_id_field = format!("job_id={}", job.id);
    let job_id_json = format!("\"job_id\":\"{}\"", job.id);
    [&event.target, &event.summary, &event.detail]
        .iter()
        .any(|value| value.contains(&job_id_field) || value.contains(&job_id_json))
}

fn successful_command_mentions(
    command_sessions: &[CommandSessionSummary],
    needles: &[&str],
) -> bool {
    command_sessions.iter().any(|command_session| {
        if command_session.state != "completed" || command_session.exit_code != Some(0) {
            return false;
        }
        let tokens = command_session_tokens(&command_session.command, &command_session.args);
        needles.iter().all(|needle| {
            let needle = needle.to_ascii_lowercase();
            tokens.iter().any(|token| token == &needle)
        })
    })
}

fn command_session_tokens(command: &str, args: &[String]) -> Vec<String> {
    std::iter::once(command)
        .chain(args.iter().map(String::as_str))
        .flat_map(|value| value.split_whitespace())
        .map(|value| {
            value
                .trim_matches(|ch: char| matches!(ch, '"' | '\'' | '`'))
                .to_ascii_lowercase()
        })
        .filter(|value| !value.is_empty())
        .collect()
}

fn path_is_under_declared_root(path: &Path, root: &Path) -> Result<bool> {
    let path = path
        .canonicalize()
        .with_context(|| format!("could not resolve cwd '{}'", path.display()))?;
    let root = root.canonicalize().with_context(|| {
        format!(
            "could not resolve declared working_dir '{}'",
            root.display()
        )
    })?;
    Ok(path.starts_with(root))
}

fn lexical_path_is_under_declared_root(path: &Path, root: &Path) -> Option<bool> {
    if !path.is_absolute() || !root.is_absolute() {
        return None;
    }
    Some(normalize_lexical_path(path).starts_with(normalize_lexical_path(root)))
}

fn context_integrity_metadata_with_session_state(
    state: &AppState,
    session: &SessionSummary,
    job: &JobSummary,
    job_id: &str,
) -> Result<Value> {
    let mut metadata = job.metadata_json.clone();
    let has_declared_git_path = declared_session_git_path(session).is_some();
    let preserve_existing_blocked = has_declared_git_path
        && metadata
            .get("session_state_evidence")
            .is_some_and(preserve_existing_session_state_blocker);
    let evidence = if preserve_existing_blocked {
        metadata
            .get("session_state_evidence")
            .cloned()
            .unwrap_or_else(|| json!({}))
    } else {
        session_state_evidence_and_refresh(state, session, job_id)?
    };
    if evidence
        .as_object()
        .is_some_and(|object| !object.is_empty())
    {
        metadata["session_state_evidence"] = evidence;
    } else if metadata.get("session_state_evidence").is_some() {
        metadata
            .as_object_mut()
            .expect("job metadata must be a JSON object")
            .remove("session_state_evidence");
    }
    Ok(metadata)
}

fn preserve_existing_session_state_blocker(evidence: &Value) -> bool {
    evidence
        .get("status")
        .and_then(Value::as_str)
        .is_some_and(|status| status == "blocked")
        && evidence
            .get("reason")
            .and_then(Value::as_str)
            .is_some_and(|reason| {
                reason.contains(
                    "stored session git metadata differed from observed disk state without a matching daemon-observed mutation",
                )
            })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct ObservedSessionGitState {
    git_head: String,
    git_branch: String,
    git_dirty: bool,
    git_untracked_count: usize,
    dirty_paths: Vec<String>,
}

fn session_state_evidence_and_refresh(
    state: &AppState,
    session: &SessionSummary,
    job_id: &str,
) -> Result<Value> {
    let Some(worktree_path) = declared_session_git_path(session) else {
        return Ok(json!({}));
    };
    if !worktree_path.is_dir() {
        return Ok(json!({
            "status": "blocked",
            "reason": "worktree missing",
            "stored": stored_session_git_state_json(session),
            "observed": {},
            "worktree_path": worktree_path.display().to_string(),
            "audit_hint": "If a daemon-observed mutation explains this drift, inspect audit_events for the matching job/session."
        }));
    }
    let observed = match observe_session_git_state(&worktree_path) {
        Ok(observed) => observed,
        Err(error) => {
            return Ok(json!({
                "status": "pending",
                "reason": format!("git rev-parse failed: {error}"),
                "stored": stored_session_git_state_json(session),
                "observed": {},
                "worktree_path": worktree_path.display().to_string(),
                "audit_hint": "Retry session-state refresh once the worktree is a readable git checkout."
            }));
        }
    };
    let stored = ObservedSessionGitState {
        git_head: session.git_head.clone(),
        git_branch: session.git_branch.clone(),
        git_dirty: session.git_dirty,
        git_untracked_count: session.git_untracked_count,
        dirty_paths: Vec::new(),
    };
    let legacy_uninitialized =
        stored.git_head.trim().is_empty() && stored.git_branch.trim().is_empty();
    let drifted = !legacy_uninitialized && !session_git_state_metadata_matches(&stored, &observed);
    let matching_receipts = if drifted {
        mutation_receipts_explaining_session_state(state, session, job_id, &stored, &observed)?
    } else {
        Vec::new()
    };
    let matching_audit = if drifted && matching_receipts.is_empty() {
        mutation_audit_explaining_session_state(state, session, job_id, &stored, &observed)?
    } else {
        None
    };
    let matching_command_session =
        if drifted && matching_receipts.is_empty() && matching_audit.is_none() {
            mutation_command_session_explaining_session_state(
                state, session, job_id, &stored, &observed,
            )?
        } else {
            None
        };
    let observed_at = unix_timestamp();
    let _ = state.store.update_session(
        &session.id,
        SessionPatch {
            git_head: Some(observed.git_head.clone()),
            git_branch: Some(observed.git_branch.clone()),
            git_dirty: Some(observed.git_dirty),
            git_untracked_count: Some(observed.git_untracked_count),
            session_state_observed_at: Some(Some(observed_at)),
            ..SessionPatch::default()
        },
    )?;

    let (status, reason, receipt_ids, audit_event_id, command_session_id) = if drifted {
        if !matching_receipts.is_empty() {
            let receipt_ids = matching_receipts
                .iter()
                .map(|receipt| receipt.id)
                .collect::<Vec<_>>();
            (
                "satisfied",
                format!(
                    "drift explained by mutation receipt(s) {}",
                    receipt_ids
                        .iter()
                        .map(ToString::to_string)
                        .collect::<Vec<_>>()
                        .join(", ")
                ),
                receipt_ids,
                None,
                None,
            )
        } else if let Some(audit) = matching_audit {
            (
                "satisfied",
                format!("drift explained by audit event {}", audit.id),
                Vec::new(),
                Some(audit.id),
                None,
            )
        } else if let Some(command_session) = matching_command_session {
            (
                "satisfied",
                format!("drift explained by command session {}", command_session.id),
                Vec::new(),
                None,
                Some(command_session.id),
            )
        } else {
            (
                "blocked",
                "stored session git metadata differed from observed disk state without a matching daemon-observed mutation".to_string(),
                Vec::new(),
                None,
                None,
            )
        }
    } else if legacy_uninitialized {
        (
            "satisfied",
            "legacy session git metadata was initialized from disk".to_string(),
            Vec::new(),
            None,
            None,
        )
    } else {
        ("satisfied", String::new(), Vec::new(), None, None)
    };

    Ok(json!({
        "status": status,
        "reason": reason,
        "stored": stored_session_git_state_json_from(&stored),
        "observed": stored_session_git_state_json_from(&observed),
        "observed_at": observed_at,
        "mutation_receipt_ids": receipt_ids,
        "audit_event_id": audit_event_id,
        "mutation_command_session_id": command_session_id,
        "audit_hint": "If a daemon-observed mutation exists but was not matched, inspect mutation_receipts and audit_events around this job/session and compare the mutation target to the stored/observed values."
    }))
}

fn session_git_state_metadata_matches(
    left: &ObservedSessionGitState,
    right: &ObservedSessionGitState,
) -> bool {
    left.git_head == right.git_head
        && left.git_branch == right.git_branch
        && left.git_dirty == right.git_dirty
        && left.git_untracked_count == right.git_untracked_count
}

fn declared_session_git_path(session: &SessionSummary) -> Option<PathBuf> {
    [session.worktree_path.as_str(), session.git_root.as_str()]
        .into_iter()
        .map(str::trim)
        .find(|value| !value.is_empty())
        .map(PathBuf::from)
        .or_else(|| {
            let has_stored_git_state =
                !session.git_head.trim().is_empty() || !session.git_branch.trim().is_empty();
            has_stored_git_state
                .then(|| session.working_dir.trim())
                .filter(|value| !value.is_empty())
                .map(PathBuf::from)
        })
}

fn observe_session_git_state(worktree_path: &Path) -> Result<ObservedSessionGitState> {
    let git_head = match git_command_stdout(worktree_path, &["rev-parse", "HEAD"]) {
        Ok(head) => head,
        Err(_) if worktree_has_unborn_head(worktree_path) => String::new(),
        Err(error) => return Err(error),
    };
    let git_branch = git_stdout(worktree_path, &["symbolic-ref", "--short", "HEAD"])
        .or_else(|| git_stdout(worktree_path, &["rev-parse", "--abbrev-ref", "HEAD"]))
        .filter(|branch| branch != "HEAD")
        .unwrap_or_default();
    let status = git_command_stdout_raw(worktree_path, &["status", "--porcelain=v1"])?;
    let dirty_paths = git_status_dirty_paths(&status);
    let git_untracked_count = status.lines().filter(|line| line.starts_with("??")).count();
    Ok(ObservedSessionGitState {
        git_head,
        git_branch,
        git_dirty: !status.trim().is_empty(),
        git_untracked_count,
        dirty_paths,
    })
}

fn git_status_dirty_paths(status: &str) -> Vec<String> {
    let mut paths = BTreeSet::new();
    for line in status.lines() {
        let line = line.trim_end();
        if line.len() < 4 {
            continue;
        }
        let path = line[3..].trim();
        if path.is_empty() {
            continue;
        }
        if let Some((from, to)) = path.split_once(" -> ") {
            if !from.trim().is_empty() {
                paths.insert(from.trim().to_string());
            }
            if !to.trim().is_empty() {
                paths.insert(to.trim().to_string());
            }
        } else {
            paths.insert(path.to_string());
        }
    }
    paths.into_iter().collect()
}

fn worktree_has_unborn_head(worktree_path: &Path) -> bool {
    git_stdout(worktree_path, &["rev-parse", "--is-inside-work-tree"]).as_deref() == Some("true")
        && git_stdout(
            worktree_path,
            &["symbolic-ref", "--quiet", "--short", "HEAD"],
        )
        .is_some()
        && git_status(worktree_path, &["rev-parse", "--verify", "--quiet", "HEAD"]).is_err()
}

fn git_command_stdout(cwd: &Path, args: &[&str]) -> Result<String> {
    Ok(git_command_stdout_raw(cwd, args)?.trim().to_string())
}

fn git_command_stdout_raw(cwd: &Path, args: &[&str]) -> Result<String> {
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(cwd)
        .args(args)
        .output()
        .with_context(|| format!("failed to run git {}", args.join(" ")))?;
    if output.status.success() {
        return Ok(String::from_utf8_lossy(&output.stdout).to_string());
    }
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    if stderr.is_empty() {
        bail!("git {} failed", args.join(" "));
    }
    bail!("{stderr}");
}

fn stored_session_git_state_json(session: &SessionSummary) -> Value {
    json!({
        "git_head": session.git_head,
        "git_branch": session.git_branch,
        "git_dirty": session.git_dirty,
        "git_untracked_count": session.git_untracked_count,
    })
}

fn stored_session_git_state_json_from(state: &ObservedSessionGitState) -> Value {
    json!({
        "git_head": state.git_head,
        "git_branch": state.git_branch,
        "git_dirty": state.git_dirty,
        "git_untracked_count": state.git_untracked_count,
        "dirty_paths": state.dirty_paths,
    })
}

fn mutation_receipts_explaining_session_state(
    state: &AppState,
    session: &SessionSummary,
    job_id: &str,
    stored: &ObservedSessionGitState,
    observed: &ObservedSessionGitState,
) -> Result<Vec<nucleus_protocol::MutationReceipt>> {
    let since = session
        .session_state_observed_at
        .unwrap_or(session.created_at)
        .saturating_sub(1);
    let mut receipts = state
        .store
        .list_mutation_receipts_for_session(&session.id)?;
    receipts.retain(|receipt| {
        receipt.job_id == job_id
            && receipt.created_at > since
            && receipt.expected_dirty == receipt.after_git_dirty
    });
    receipts.sort_by_key(|receipt| (receipt.created_at, receipt.id));

    if let Some(receipt) = receipts.iter().find(|receipt| {
        session_git_state_metadata_matches(&mutation_receipt_before_state(receipt), stored)
            && session_git_state_metadata_matches(&mutation_receipt_after_state(receipt), observed)
            && mutation_receipt_paths_cover_observed(
                &receipt.paths.iter().cloned().collect::<BTreeSet<_>>(),
                observed,
            )
    }) {
        return Ok(vec![receipt.clone()]);
    }

    let mut current = stored.clone();
    let mut matched = Vec::new();
    let mut covered_paths = BTreeSet::new();
    for receipt in receipts {
        let before = mutation_receipt_before_state(&receipt);
        if !session_git_state_metadata_matches(&current, &before) {
            continue;
        }
        current = mutation_receipt_after_state(&receipt);
        for path in &receipt.paths {
            covered_paths.insert(path.clone());
        }
        matched.push(receipt);
        if session_git_state_metadata_matches(&current, observed)
            && mutation_receipt_paths_cover_observed(&covered_paths, observed)
        {
            return Ok(matched);
        }
    }

    Ok(Vec::new())
}

fn mutation_receipt_before_state(
    receipt: &nucleus_protocol::MutationReceipt,
) -> ObservedSessionGitState {
    ObservedSessionGitState {
        git_head: receipt.before_git_head.clone(),
        git_branch: receipt.before_git_branch.clone(),
        git_dirty: receipt.before_git_dirty,
        git_untracked_count: receipt.before_git_untracked_count,
        dirty_paths: Vec::new(),
    }
}

fn mutation_receipt_after_state(
    receipt: &nucleus_protocol::MutationReceipt,
) -> ObservedSessionGitState {
    ObservedSessionGitState {
        git_head: receipt.after_git_head.clone(),
        git_branch: receipt.after_git_branch.clone(),
        git_dirty: receipt.after_git_dirty,
        git_untracked_count: receipt.after_git_untracked_count,
        dirty_paths: Vec::new(),
    }
}

fn mutation_receipt_paths_cover_observed(
    covered_paths: &BTreeSet<String>,
    observed: &ObservedSessionGitState,
) -> bool {
    observed.dirty_paths.is_empty()
        || observed
            .dirty_paths
            .iter()
            .all(|path| covered_paths.contains(path))
}

fn mutation_audit_explaining_session_state(
    state: &AppState,
    session: &SessionSummary,
    job_id: &str,
    stored: &ObservedSessionGitState,
    observed: &ObservedSessionGitState,
) -> Result<Option<nucleus_protocol::AuditEvent>> {
    let since = session
        .session_state_observed_at
        .unwrap_or(session.created_at)
        .saturating_sub(1);
    let events = state.store.list_audit_events_since(since)?;
    Ok(events.into_iter().find(|event| {
        let haystack = format!(
            "{} {} {} {}",
            event.kind, event.target, event.summary, event.detail
        )
        .to_ascii_lowercase();
        let mentions_scope = event.target.contains(&session.id)
            || event.target.contains(job_id)
            || event.detail.contains(&session.id)
            || event.detail.contains(job_id)
            || event.summary.contains(&session.id)
            || event.summary.contains(job_id);
        let mutation_succeeded = event.status.eq_ignore_ascii_case("success");
        mentions_scope
            && mutation_succeeded
            && haystack.contains("git")
            && text_mentions_session_state_mutating_git(&haystack)
            && text_matches_session_state_transition(&haystack, stored, observed)
    }))
}

fn text_matches_session_state_transition(
    text: &str,
    stored: &ObservedSessionGitState,
    observed: &ObservedSessionGitState,
) -> bool {
    if stored.git_head != observed.git_head && !text_mentions_git_head(text, &observed.git_head) {
        return false;
    }
    if stored.git_branch != observed.git_branch {
        let branch = observed.git_branch.to_ascii_lowercase();
        if branch.is_empty() {
            if !text.contains("branch=") && !text.contains("detached") {
                return false;
            }
        } else if !branch.is_empty() && !text.contains(&branch) {
            return false;
        }
    }
    if stored.git_dirty != observed.git_dirty {
        let expected = format!("dirty={}", observed.git_dirty);
        let expected_alt = format!("git_dirty={}", observed.git_dirty);
        if !text.contains(&expected) && !text.contains(&expected_alt) {
            return false;
        }
    }
    if stored.git_untracked_count != observed.git_untracked_count {
        let expected = format!("untracked={}", observed.git_untracked_count);
        let expected_alt = format!("git_untracked_count={}", observed.git_untracked_count);
        if !text.contains(&expected) && !text.contains(&expected_alt) {
            return false;
        }
    }
    true
}

fn text_mentions_git_head(text: &str, head: &str) -> bool {
    if head.trim().is_empty() {
        return text.contains("head=") || text.contains("unborn");
    }
    let normalized = head.to_ascii_lowercase();
    text.contains(&normalized)
        || normalized
            .get(..12)
            .is_some_and(|short| !short.is_empty() && text.contains(short))
}

fn mutation_command_session_explaining_session_state(
    state: &AppState,
    session: &SessionSummary,
    job_id: &str,
    stored: &ObservedSessionGitState,
    observed: &ObservedSessionGitState,
) -> Result<Option<CommandSessionSummary>> {
    let Ok(detail) = state.store.get_job(job_id) else {
        return Ok(None);
    };
    Ok(detail.command_sessions.into_iter().find(|command_session| {
        command_session_is_newer_than_session_state(session, command_session)
            && is_session_git_mutation_command_session(session, command_session)
            && command_session_matches_session_state_transition(command_session, stored, observed)
    }))
}

fn command_session_matches_session_state_transition(
    command_session: &CommandSessionSummary,
    stored: &ObservedSessionGitState,
    observed: &ObservedSessionGitState,
) -> bool {
    let Some((_git_cwd, subcommand)) = command_session_git_invocation(command_session) else {
        return false;
    };
    let mut text = format!(
        "{} {} {} {} {}",
        command_session.title,
        command_session.command,
        command_session.args.join(" "),
        command_session.branch,
        command_session.worktree_path
    )
    .to_ascii_lowercase();
    text.push(' ');
    text.push_str(&subcommand.to_ascii_lowercase());

    if stored.git_head != observed.git_head
        && !text_mentions_git_head(&text, &observed.git_head)
        && !git_subcommand_can_move_head(&subcommand)
    {
        return false;
    }
    if stored.git_branch != observed.git_branch {
        let branch = observed.git_branch.to_ascii_lowercase();
        if branch.is_empty() {
            if !text.contains("branch=")
                && !text.contains("detached")
                && !git_subcommand_can_change_branch(&subcommand)
            {
                return false;
            }
        } else if !text.contains(&branch) && !git_subcommand_can_change_branch(&subcommand) {
            return false;
        }
    }
    if stored.git_dirty != observed.git_dirty
        && !text.contains(&format!("dirty={}", observed.git_dirty))
        && !text.contains(&format!("git_dirty={}", observed.git_dirty))
        && !git_subcommand_can_change_worktree_status(&subcommand)
    {
        return false;
    }
    if stored.git_untracked_count != observed.git_untracked_count
        && !text.contains(&format!("untracked={}", observed.git_untracked_count))
        && !text.contains(&format!(
            "git_untracked_count={}",
            observed.git_untracked_count
        ))
        && !git_subcommand_can_change_worktree_status(&subcommand)
    {
        return false;
    }
    true
}

fn git_subcommand_can_move_head(subcommand: &str) -> bool {
    matches!(
        subcommand,
        "checkout"
            | "cherry-pick"
            | "commit"
            | "merge"
            | "pull"
            | "rebase"
            | "reset"
            | "revert"
            | "switch"
    )
}

fn git_subcommand_can_change_branch(subcommand: &str) -> bool {
    matches!(subcommand, "checkout" | "switch")
}

fn git_subcommand_can_change_worktree_status(subcommand: &str) -> bool {
    matches!(
        subcommand,
        "add"
            | "apply"
            | "checkout"
            | "cherry-pick"
            | "clean"
            | "commit"
            | "merge"
            | "mv"
            | "pull"
            | "rebase"
            | "reset"
            | "restore"
            | "revert"
            | "rm"
            | "stash"
            | "switch"
    )
}

fn command_session_is_newer_than_session_state(
    session: &SessionSummary,
    command_session: &CommandSessionSummary,
) -> bool {
    let since = session
        .session_state_observed_at
        .unwrap_or(session.created_at.saturating_sub(1));
    command_session
        .completed_at
        .or(command_session.started_at)
        .unwrap_or(command_session.updated_at)
        >= since
}

fn is_session_git_mutation_command_session(
    session: &SessionSummary,
    command_session: &CommandSessionSummary,
) -> bool {
    if command_session.state != "completed" || command_session.exit_code != Some(0) {
        return false;
    }
    if !command_session.session_id.is_empty() && command_session.session_id != session.id {
        return false;
    }
    let Some(declared_git_path) = declared_session_git_path(session) else {
        return false;
    };
    let Some((git_cwd, subcommand)) = command_session_git_invocation(command_session) else {
        return false;
    };
    if !GIT_SESSION_STATE_MUTATING_SUBCOMMANDS.contains(&subcommand.as_str()) {
        return false;
    }
    path_is_under_declared_root(&git_cwd, &declared_git_path).unwrap_or(false)
}

fn text_mentions_session_state_mutating_git(text: &str) -> bool {
    text.split(|ch: char| !(ch.is_ascii_alphanumeric() || ch == '-'))
        .any(|token| GIT_SESSION_STATE_MUTATING_SUBCOMMANDS.contains(&token))
}

const GIT_SESSION_STATE_MUTATING_SUBCOMMANDS: &[&str] = &[
    "add",
    "apply",
    "checkout",
    "cherry-pick",
    "clean",
    "commit",
    "merge",
    "mv",
    "pull",
    "rebase",
    "reset",
    "restore",
    "revert",
    "rm",
    "stash",
    "switch",
];

fn command_session_git_invocation(
    command_session: &CommandSessionSummary,
) -> Option<(PathBuf, String)> {
    let base_cwd = command_session.cwd.trim();
    if base_cwd.is_empty() {
        return None;
    }
    let executable = Path::new(command_session.command.trim())
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or(command_session.command.trim());
    if executable == "git" {
        return parse_git_invocation_from_args(PathBuf::from(base_cwd), &command_session.args);
    }
    if !is_shell_executable(executable) {
        return None;
    }
    let shell_command = shell_command_arg(&command_session.args)?;
    let mut tokens = split_simple_shell_words(shell_command)?;
    if tokens
        .first()
        .is_some_and(|token| token == "exec" || token == "command")
    {
        tokens.remove(0);
    }
    if tokens.first().is_none_or(|token| token != "git") {
        return None;
    }
    parse_git_invocation_from_args(PathBuf::from(base_cwd), &tokens[1..])
}

fn parse_git_invocation_from_args(
    mut git_cwd: PathBuf,
    args: &[String],
) -> Option<(PathBuf, String)> {
    let mut index = 0;
    while index < args.len() {
        let arg = args[index].as_str();
        if arg == "-C" {
            let value = args.get(index + 1)?;
            git_cwd = resolve_git_c_option_path(&git_cwd, value);
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("-C") {
            if value.is_empty() {
                return None;
            }
            git_cwd = resolve_git_c_option_path(&git_cwd, value);
            index += 1;
            continue;
        }
        if arg == "--git-dir" {
            let value = args.get(index + 1)?;
            git_cwd = resolve_git_dir_worktree_path(&git_cwd, value);
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--git-dir=") {
            if value.is_empty() {
                return None;
            }
            git_cwd = resolve_git_dir_worktree_path(&git_cwd, value);
            index += 1;
            continue;
        }
        if arg == "--work-tree" {
            let value = args.get(index + 1)?;
            git_cwd = resolve_git_c_option_path(&git_cwd, value);
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--work-tree=") {
            if value.is_empty() {
                return None;
            }
            git_cwd = resolve_git_c_option_path(&git_cwd, value);
            index += 1;
            continue;
        }
        if git_global_option_takes_value(arg) {
            args.get(index + 1)?;
            index += 2;
            continue;
        }
        if git_inline_global_option(arg) {
            index += 1;
            continue;
        }
        if arg.starts_with('-') {
            return None;
        }
        return Some((git_cwd, arg.to_string()));
    }
    None
}

fn is_shell_executable(executable: &str) -> bool {
    matches!(executable, "sh" | "bash" | "zsh" | "dash")
}

fn shell_command_arg(args: &[String]) -> Option<&str> {
    let mut index = 0;
    while index < args.len() {
        let arg = args[index].as_str();
        if shell_arg_requests_command(arg) {
            return args.get(index + 1).map(String::as_str);
        }
        index += 1;
    }
    None
}

fn shell_arg_requests_command(arg: &str) -> bool {
    if arg == "-c" {
        return true;
    }
    let Some(flags) = arg.strip_prefix('-') else {
        return false;
    };
    !flags.starts_with('-')
        && flags.contains('c')
        && flags.chars().all(shell_short_flag_can_cluster)
}

fn shell_short_flag_can_cluster(ch: char) -> bool {
    matches!(
        ch,
        'a' | 'b'
            | 'c'
            | 'e'
            | 'f'
            | 'h'
            | 'i'
            | 'k'
            | 'l'
            | 'm'
            | 'n'
            | 'p'
            | 'r'
            | 's'
            | 't'
            | 'u'
            | 'v'
            | 'x'
            | 'B'
            | 'C'
            | 'E'
            | 'H'
            | 'P'
            | 'T'
    )
}

fn split_simple_shell_words(input: &str) -> Option<Vec<String>> {
    let mut words = Vec::new();
    let mut current = String::new();
    let mut chars = input.chars().peekable();
    let mut quote = None;
    while let Some(ch) = chars.next() {
        match quote {
            Some('\'') => {
                if ch == '\'' {
                    quote = None;
                } else {
                    current.push(ch);
                }
            }
            Some('"') => {
                if ch == '"' {
                    quote = None;
                } else if ch == '\\' {
                    current.push(chars.next()?);
                } else {
                    current.push(ch);
                }
            }
            _ => {
                if ch.is_whitespace() {
                    if !current.is_empty() {
                        words.push(std::mem::take(&mut current));
                    }
                } else if ch == '\'' || ch == '"' {
                    quote = Some(ch);
                } else if ch == '\\' {
                    current.push(chars.next()?);
                } else if matches!(ch, ';' | '&' | '|' | '<' | '>' | '(' | ')' | '`' | '$') {
                    return None;
                } else {
                    current.push(ch);
                }
            }
        }
    }
    if quote.is_some() {
        return None;
    }
    if !current.is_empty() {
        words.push(current);
    }
    Some(words)
}

fn resolve_git_c_option_path(base_cwd: &Path, value: &str) -> PathBuf {
    let path = Path::new(value);
    if path.is_absolute() {
        path.to_path_buf()
    } else {
        base_cwd.join(path)
    }
}

fn resolve_git_dir_worktree_path(base_cwd: &Path, value: &str) -> PathBuf {
    let git_dir = resolve_git_c_option_path(base_cwd, value);
    if git_dir.file_name().and_then(|name| name.to_str()) == Some(".git") {
        git_dir.parent().map(Path::to_path_buf).unwrap_or(git_dir)
    } else {
        git_dir
    }
}

fn git_global_option_takes_value(arg: &str) -> bool {
    matches!(arg, "-c" | "--config-env" | "--namespace")
}

fn git_inline_global_option(arg: &str) -> bool {
    arg.starts_with("-c")
        || arg == "-p"
        || arg == "-P"
        || arg.starts_with("--config-env=")
        || arg.starts_with("--exec-path=")
        || arg.starts_with("--namespace=")
        || matches!(
            arg,
            "--bare"
                | "--exec-path"
                | "--html-path"
                | "--info-path"
                | "--man-path"
                | "--no-pager"
                | "--paginate"
                | "--no-replace-objects"
                | "--no-optional-locks"
                | "--literal-pathspecs"
                | "--glob-pathspecs"
                | "--noglob-pathspecs"
                | "--icase-pathspecs"
        )
}

fn context_integrity_patch(
    state: &AppState,
    session: &SessionSummary,
    job: &JobSummary,
) -> JobPatch {
    let worktree_path = session_worktree_probe_path(session);
    let expected_origin_url = expected_project_origin_url(state, session);
    let expected_git_branch = session.git_branch.trim().to_string();
    let base_ref = session_base_ref(session);
    let base_ref_name = base_ref.display_ref();
    let mut patch = JobPatch {
        worktree_base_ref: Some(base_ref_name.clone()),
        expected_origin_url: Some(expected_origin_url.clone()),
        expected_git_branch: Some(expected_git_branch.clone()),
        ..JobPatch::default()
    };

    let Some(worktree_path) = worktree_path else {
        patch.worktree_base_status = Some("not_applicable_missing_context".to_string());
        patch.branch_repo_status = Some("not_applicable_missing_context".to_string());
        patch.worktree_base_reason = Some("session has no declared worktree path".to_string());
        patch.branch_repo_reason = Some("session has no declared worktree path".to_string());
        return patch;
    };

    if git_stdout(&worktree_path, &["rev-parse", "--show-toplevel"]).is_none() {
        patch.worktree_base_status = Some("not_applicable_missing_context".to_string());
        patch.branch_repo_status = Some("not_applicable_missing_context".to_string());
        patch.worktree_base_reason =
            Some("declared worktree path is not a git checkout".to_string());
        patch.branch_repo_reason = Some("declared worktree path is not a git checkout".to_string());
        return patch;
    }

    let observed_origin = git_stdout(&worktree_path, &["remote", "get-url", "origin"])
        .map(|url| redact_git_remote_url_userinfo(&url));
    let observed_branch = git_stdout(&worktree_path, &["symbolic-ref", "--short", "HEAD"])
        .or_else(|| git_stdout(&worktree_path, &["rev-parse", "--abbrev-ref", "HEAD"]))
        .unwrap_or_default();
    let head_sha = git_stdout(&worktree_path, &["rev-parse", "HEAD"]).unwrap_or_default();

    patch.worktree_origin_url = Some(observed_origin.clone().unwrap_or_default());
    patch.observed_git_branch = Some(observed_branch.clone());
    patch.worktree_head_sha = Some(head_sha.clone());

    patch.branch_repo_status = Some(branch_repo_status(
        observed_origin.as_deref(),
        &expected_origin_url,
        &observed_branch,
        &expected_git_branch,
    ));
    patch.branch_repo_reason = Some(branch_repo_reason(
        observed_origin.as_deref(),
        &expected_origin_url,
        &observed_branch,
        &expected_git_branch,
    ));

    if observed_origin.is_none() {
        patch.worktree_base_status = Some("blocked".to_string());
        patch.worktree_base_reason = Some("no canonical remote configured".to_string());
        patch.canonical_base_sha = Some(String::new());
        patch.worktree_behind_by = Some(None);
        return patch;
    }

    let override_value = job.metadata_json.get("worktree_base_override");
    let override_present = override_value.is_some_and(|value| !value.is_null());
    let override_allowed_behind_value =
        override_value.and_then(|value| value.get("allowed_behind_by"));
    let override_allowed_behind = override_allowed_behind_value.and_then(Value::as_i64);
    let override_reason = override_value
        .and_then(|value| value.get("reason"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or("worktree_base_override metadata is present");

    if override_present && override_allowed_behind_value.is_none() {
        patch.worktree_base_status = Some("waived".to_string());
        patch.worktree_base_reason = Some(override_reason.to_string());
        patch.worktree_behind_by = Some(None);
        return patch;
    }

    let canonical_display = base_ref.display_ref();
    let canonical_ref = format!("refs/remotes/{}/{}", base_ref.remote, base_ref.branch);
    let fetch_refspec = format!("+refs/heads/{}:{canonical_ref}", base_ref.branch);
    let fetch = git_fetch_status(&worktree_path, &["fetch", &base_ref.remote, &fetch_refspec]);
    if let Err(error) = fetch {
        patch.worktree_base_status = Some("pending".to_string());
        patch.worktree_base_reason = Some(format!("could not reach canonical: {error}"));
        patch.canonical_base_sha = Some(String::new());
        patch.worktree_behind_by = Some(None);
        return patch;
    }

    let canonical_sha = git_stdout(&worktree_path, &["rev-parse", &canonical_ref])
        .or_else(|| git_stdout(&worktree_path, &["rev-parse", &canonical_display]));
    let Some(canonical_sha) = canonical_sha else {
        patch.worktree_base_status = Some("pending".to_string());
        patch.worktree_base_reason =
            Some(format!("could not resolve canonical {canonical_display}"));
        patch.canonical_base_sha = Some(String::new());
        patch.worktree_behind_by = Some(None);
        return patch;
    };

    let behind_by = if git_status(
        &worktree_path,
        &["merge-base", "--is-ancestor", &canonical_sha, "HEAD"],
    )
    .is_ok()
    {
        0
    } else {
        let Some(behind_by) = git_stdout(
            &worktree_path,
            &["rev-list", "--count", &format!("HEAD..{canonical_sha}")],
        )
        .and_then(|value| value.parse::<i64>().ok()) else {
            patch.worktree_base_status = Some("pending".to_string());
            patch.worktree_base_reason =
                Some("could not compute worktree commits behind canonical".to_string());
            patch.canonical_base_sha = Some(canonical_sha);
            patch.worktree_behind_by = Some(None);
            return patch;
        };
        behind_by
    };
    let allowed_behind = override_allowed_behind.unwrap_or(0).max(0);

    patch.canonical_base_sha = Some(canonical_sha);
    patch.worktree_behind_by = Some(Some(behind_by));
    if behind_by > allowed_behind {
        patch.worktree_base_status = Some("blocked".to_string());
        patch.worktree_base_reason = Some(format!(
            "behind canonical by {behind_by} commit(s); allowed threshold is {allowed_behind}"
        ));
    } else if override_present {
        patch.worktree_base_status = Some("waived".to_string());
        patch.worktree_base_reason = Some(override_reason.to_string());
    } else {
        patch.worktree_base_status = Some("satisfied".to_string());
        patch.worktree_base_reason = Some(String::new());
    }

    patch
}

fn session_worktree_probe_path(session: &SessionSummary) -> Option<PathBuf> {
    [
        session.worktree_path.as_str(),
        session.working_dir.as_str(),
        session.git_root.as_str(),
    ]
    .into_iter()
    .map(str::trim)
    .filter(|value| !value.is_empty())
    .map(PathBuf::from)
    .find(|path| path.is_dir())
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct SessionBaseRef {
    remote: String,
    branch: String,
}

impl SessionBaseRef {
    fn origin(branch: &str) -> Self {
        Self {
            remote: "origin".to_string(),
            branch: branch.to_string(),
        }
    }

    fn display_ref(&self) -> String {
        if self.remote == "origin" {
            self.branch.clone()
        } else {
            format!("{}/{}", self.remote, self.branch)
        }
    }
}

fn session_base_ref(session: &SessionSummary) -> SessionBaseRef {
    let base = session.git_base_ref.trim();
    if !base.is_empty() {
        if let Some(branch) = base.strip_prefix("refs/heads/") {
            return SessionBaseRef::origin(branch);
        }
        if let Some((remote, branch)) = parse_remote_tracking_ref(base) {
            return SessionBaseRef {
                remote: remote.to_string(),
                branch: branch.to_string(),
            };
        }
        if let Some(branch) = base.strip_prefix("origin/") {
            return SessionBaseRef::origin(branch);
        }
        return SessionBaseRef::origin(base);
    }
    let remote = session.git_remote_tracking_branch.trim();
    if !remote.is_empty() {
        if let Some((remote_name, branch)) =
            parse_remote_tracking_ref(remote).or_else(|| remote.split_once('/'))
        {
            return SessionBaseRef {
                remote: remote_name.to_string(),
                branch: branch.to_string(),
            };
        }
        return SessionBaseRef::origin(remote);
    }
    SessionBaseRef::origin("dev")
}

fn parse_remote_tracking_ref(value: &str) -> Option<(&str, &str)> {
    value
        .strip_prefix("refs/remotes/")
        .and_then(|remote_ref| remote_ref.split_once('/'))
}

fn expected_project_origin_url(state: &AppState, session: &SessionSummary) -> String {
    if !session.project_id.trim().is_empty() {
        if let Ok(project) = state.store.resolve_project(&session.project_id) {
            if !project.origin_url.trim().is_empty() {
                return redact_git_remote_url_userinfo(&project.origin_url);
            }
        }
    }
    let project_path = session.project_path.trim();
    if project_path.is_empty() {
        return String::new();
    }
    git_stdout(Path::new(project_path), &["remote", "get-url", "origin"])
        .map(|url| redact_git_remote_url_userinfo(&url))
        .unwrap_or_default()
}

fn branch_repo_status(
    observed_origin: Option<&str>,
    expected_origin: &str,
    observed_branch: &str,
    expected_branch: &str,
) -> String {
    if observed_origin.is_none() {
        return "blocked".to_string();
    }
    if expected_origin.trim().is_empty() && expected_branch.trim().is_empty() {
        return "not_applicable_missing_context".to_string();
    }
    if branch_repo_mismatches(
        observed_origin,
        expected_origin,
        observed_branch,
        expected_branch,
    )
    .is_empty()
    {
        "satisfied".to_string()
    } else {
        "blocked".to_string()
    }
}

fn branch_repo_reason(
    observed_origin: Option<&str>,
    expected_origin: &str,
    observed_branch: &str,
    expected_branch: &str,
) -> String {
    if observed_origin.is_none() {
        return "no canonical remote configured".to_string();
    }
    if expected_origin.trim().is_empty() && expected_branch.trim().is_empty() {
        return "session has no declared project origin or git_branch".to_string();
    }
    let mismatches = branch_repo_mismatches(
        observed_origin,
        expected_origin,
        observed_branch,
        expected_branch,
    );
    if mismatches.is_empty() {
        String::new()
    } else {
        mismatches.join("; ")
    }
}

fn branch_repo_mismatches(
    observed_origin: Option<&str>,
    expected_origin: &str,
    observed_branch: &str,
    expected_branch: &str,
) -> Vec<String> {
    let mut mismatches = Vec::new();
    let observed_origin = observed_origin.unwrap_or_default();
    if !expected_origin.trim().is_empty()
        && normalize_git_origin_url(observed_origin) != normalize_git_origin_url(expected_origin)
    {
        mismatches.push("origin URL mismatch".to_string());
    }
    if !expected_branch.trim().is_empty() && observed_branch.trim() != expected_branch.trim() {
        mismatches.push("branch mismatch".to_string());
    }
    mismatches
}

fn normalize_git_origin_url(url: &str) -> String {
    let mut value = url.trim().trim_end_matches('/').to_string();
    let url_form = if let Some(rest) = value
        .strip_prefix("https://")
        .or_else(|| value.strip_prefix("http://"))
    {
        value = rest.to_string();
        true
    } else if let Some(rest) = value.strip_prefix("ssh://") {
        value = rest.to_string();
        true
    } else {
        false
    };
    if let Some((_, rest)) = value.split_once('@') {
        value = rest.to_string();
    }
    if let Some(colon_index) = value.find(':') {
        let slash_index = value.find('/').unwrap_or(usize::MAX);
        if colon_index < slash_index {
            if url_form {
                value.replace_range(colon_index..slash_index, "");
            } else {
                value.replace_range(colon_index..=colon_index, "/");
            }
        }
    }
    let value = value.trim_end_matches(".git");
    if let Some((host, path)) = value.split_once('/') {
        format!("{}/{}", host.to_ascii_lowercase(), path)
    } else {
        value.to_ascii_lowercase()
    }
}

fn redact_git_remote_url_userinfo(url: &str) -> String {
    let value = url.trim();
    let Some(scheme_index) = value.find("://") else {
        return value.to_string();
    };
    let authority_start = scheme_index + "://".len();
    let rest = &value[authority_start..];
    let slash_index = rest.find('/').unwrap_or(usize::MAX);
    let Some(at_index) = rest.find('@') else {
        return value.to_string();
    };
    if at_index < slash_index {
        format!("{}{}", &value[..authority_start], &rest[at_index + 1..])
    } else {
        value.to_string()
    }
}

fn git_stdout(cwd: &Path, args: &[&str]) -> Option<String> {
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(cwd)
        .args(args)
        .output()
        .ok()?;
    if !output.status.success() {
        return None;
    }
    let stdout = String::from_utf8(output.stdout).ok()?;
    let value = stdout.trim();
    if value.is_empty() {
        None
    } else {
        Some(value.to_string())
    }
}

fn git_status(cwd: &Path, args: &[&str]) -> Result<()> {
    let output = std::process::Command::new("git")
        .arg("-C")
        .arg(cwd)
        .args(args)
        .output()
        .with_context(|| format!("failed to run git {}", args.join(" ")))?;
    if output.status.success() {
        return Ok(());
    }
    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    let stdout = String::from_utf8_lossy(&output.stdout).trim().to_string();
    let detail = if !stderr.is_empty() { stderr } else { stdout };
    if detail.is_empty() {
        bail!("git {} failed", args.join(" "));
    }
    bail!("{detail}");
}

fn git_fetch_status(cwd: &Path, args: &[&str]) -> Result<()> {
    let mut child = std::process::Command::new("git")
        .arg("-C")
        .arg(cwd)
        .args(args)
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .env("GIT_TERMINAL_PROMPT", "0")
        .env("GIT_ASKPASS", "true")
        .env("SSH_ASKPASS", "true")
        .env("GIT_SSH_COMMAND", "ssh -o BatchMode=yes")
        .spawn()
        .with_context(|| format!("failed to run git {}", args.join(" ")))?;
    let started = Instant::now();
    loop {
        if child
            .try_wait()
            .with_context(|| format!("failed to poll git {}", args.join(" ")))?
            .is_some()
        {
            let output = child
                .wait_with_output()
                .with_context(|| format!("failed to collect git {}", args.join(" ")))?;
            if output.status.success() {
                return Ok(());
            }
            bail!(
                "git {} failed: {}",
                args.join(" "),
                String::from_utf8_lossy(&output.stderr).trim()
            );
        }
        if started.elapsed() >= Duration::from_secs(CONTEXT_INTEGRITY_FETCH_TIMEOUT_SECS) {
            let _ = child.kill();
            let output = child
                .wait_with_output()
                .with_context(|| format!("failed to collect timed-out git {}", args.join(" ")))?;
            bail!(
                "git {} timed out after {}s: {}",
                args.join(" "),
                CONTEXT_INTEGRITY_FETCH_TIMEOUT_SECS,
                String::from_utf8_lossy(&output.stderr).trim()
            );
        }
        std::thread::sleep(Duration::from_millis(100));
    }
}

fn context_integrity_start_blocker(job: &JobSummary) -> Option<String> {
    job.completion_gates
        .iter()
        .find(|gate| {
            matches!(
                gate.id.as_str(),
                "worktree_base_fresh"
                    | "branch_repo_consistent"
                    | "cwd_consistent"
                    | "session_state_consistent"
            ) && gate.state == "blocked"
        })
        .map(|gate| gate.summary.clone())
}

async fn block_job_for_context_integrity(
    state: &AppState,
    session: &SessionDetail,
    worker: &mut WorkerSummary,
    blocker: &str,
) -> Result<()> {
    let summary = format!("Context integrity blocked: {blocker}");
    state.store.update_job(
        &worker.job_id,
        JobPatch {
            state: Some("blocked".to_string()),
            result_summary: Some(summary.clone()),
            last_error: Some(String::new()),
            ..JobPatch::default()
        },
    )?;
    *worker = state.store.update_worker(
        &worker.id,
        WorkerPatch {
            state: Some("completed".to_string()),
            last_error: Some(String::new()),
            ..WorkerPatch::default()
        },
    )?;
    state.store.update_session(
        &session.session.id,
        SessionPatch {
            state: Some("active".to_string()),
            last_error: Some(String::new()),
            ..SessionPatch::default()
        },
    )?;
    let _ = state.store.append_job_event(JobEventRecord {
        job_id: worker.job_id.clone(),
        worker_id: Some(worker.id.clone()),
        event_type: "job.blocked".to_string(),
        status: "blocked".to_string(),
        summary,
        detail: blocker.to_string(),
        data_json: json!({
            "terminal_status": "blocked",
            "blocked": true,
            "reason": "context_integrity",
        }),
    });
    publish_job_updated(state, &state.store.get_job(&worker.job_id)?.job).await;
    publish_worker_updated(state, worker).await;
    if let Ok(updated) = state.store.get_session(&session.session.id) {
        let _ = publish_session_event(state, updated).await;
    }
    publish_terminal_job_event(state, &state.store.get_job(&worker.job_id)?.job).await;
    let _ = publish_overview_event(state).await;
    Ok(())
}

fn context_integrity_event_summary(job: &JobSummary) -> String {
    let cwd_status = job
        .command_session_cwd_evidence_json
        .as_deref()
        .and_then(|value| serde_json::from_str::<Value>(value).ok())
        .and_then(|value| {
            value
                .get("status")
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .unwrap_or_default();
    let session_state_status = job
        .metadata_json
        .get("session_state_evidence")
        .and_then(|value| value.get("status"))
        .and_then(Value::as_str)
        .unwrap_or_default();
    let target_entity_status =
        evidence_status_from_json(job.target_entity_evidence_json.as_deref());
    let process_state_status =
        evidence_status_from_json(job.process_state_evidence_json.as_deref());
    match (
        job.worktree_base_status.as_str(),
        job.branch_repo_status.as_str(),
        cwd_status.as_str(),
        session_state_status,
        target_entity_status.as_str(),
        process_state_status.as_str(),
    ) {
        ("blocked", _, _, _, _, _)
        | (_, "blocked", _, _, _, _)
        | (_, _, "blocked", _, _, _)
        | (_, _, _, "blocked", _, _)
        | (_, _, _, _, "blocked", _)
        | (_, _, _, _, _, "blocked") => "Context integrity is blocked.".to_string(),
        ("pending", _, _, _, _, _)
        | (_, "pending", _, _, _, _)
        | (_, _, "pending", _, _, _)
        | (_, _, _, "pending", _, _)
        | (_, _, _, _, "pending", _)
        | (_, _, _, _, _, "pending") => "Context integrity is pending.".to_string(),
        ("", "", "", "", "", "") => "Context integrity did not run for this job.".to_string(),
        _ => "Context integrity evidence recorded.".to_string(),
    }
}

fn evidence_status_from_json(value: Option<&str>) -> String {
    value
        .and_then(|value| serde_json::from_str::<Value>(value).ok())
        .and_then(|value| {
            value
                .get("status")
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .unwrap_or_default()
}

fn context_integrity_event_detail(job: &JobSummary) -> String {
    let base = if job.worktree_base_reason.trim().is_empty() {
        job.worktree_base_status.clone()
    } else {
        format!(
            "{} ({})",
            job.worktree_base_status, job.worktree_base_reason
        )
    };
    let branch = if job.branch_repo_reason.trim().is_empty() {
        job.branch_repo_status.clone()
    } else {
        format!("{} ({})", job.branch_repo_status, job.branch_repo_reason)
    };
    let cwd = job
        .command_session_cwd_evidence_json
        .as_deref()
        .and_then(|value| serde_json::from_str::<Value>(value).ok())
        .map(|value| {
            let status = value
                .get("status")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let reason = value
                .get("reason")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if reason.trim().is_empty() {
                status.to_string()
            } else {
                format!("{status} ({reason})")
            }
        })
        .unwrap_or_default();
    let session_state = job
        .metadata_json
        .get("session_state_evidence")
        .map(|value| {
            let status = value
                .get("status")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let reason = value
                .get("reason")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if reason.trim().is_empty() {
                status.to_string()
            } else {
                format!("{status} ({reason})")
            }
        })
        .unwrap_or_default();
    let target_entity = evidence_detail_from_json(job.target_entity_evidence_json.as_deref());
    let process_state = evidence_detail_from_json(job.process_state_evidence_json.as_deref());
    format!(
        "worktree_base={base}; branch_repo={branch}; cwd={cwd}; session_state={session_state}; target_entity={target_entity}; process_state={process_state}"
    )
}

fn evidence_detail_from_json(value: Option<&str>) -> String {
    value
        .and_then(|value| serde_json::from_str::<Value>(value).ok())
        .map(|value| {
            let status = value
                .get("status")
                .and_then(Value::as_str)
                .unwrap_or_default();
            let reason = value
                .get("reason")
                .and_then(Value::as_str)
                .unwrap_or_default();
            if reason.trim().is_empty() {
                status.to_string()
            } else {
                format!("{status} ({reason})")
            }
        })
        .unwrap_or_default()
}

fn add_budget_guidance(
    prompt: String,
    worker: &WorkerSummary,
    step_count: usize,
    tool_call_count: usize,
) -> String {
    let final_step = worker.max_steps > 0 && worker.max_steps.saturating_sub(step_count) <= 1;
    let final_action =
        worker.max_tool_calls > 0 && worker.max_tool_calls.saturating_sub(tool_call_count) <= 1;

    if !final_step && !final_action {
        return prompt;
    }

    format!(
        "{}\n\nBudget note: this run is at the edge of its current {}budget. Prefer final_answer now with a clear summary of completed work, latest evidence, remaining blocker, and exact continuation point. Only call another tool if that single action is decisive and worth checkpointing immediately afterward.",
        prompt,
        if final_step && final_action {
            "step and action "
        } else if final_step {
            "step "
        } else {
            "action "
        }
    )
}

fn build_tool_result_prompt(tool: &str, summary: &str, result: &Value) -> String {
    format!(
        "Tool result for {}.\nReason for the call: {}\nStructured result:\n{}\n\
Return one JSON action for the next step. If the work is done, return final_answer with a complete user-facing answer. If the work is not done but a durable checkpoint is useful, return progress_update and continue afterward.",
        tool,
        summary,
        format_tool_result(result)
    )
}

fn build_tool_denied_prompt(tool: &str, summary: &str, reason: &str) -> String {
    format!(
        "Nucleus did not allow {}.\nReason for the proposed action: {}\nResolution detail: {}\n\
Return one JSON action for the next step. If the work can still be completed without this mutation, return final_answer with a complete user-facing answer.",
        tool, summary, reason
    )
}

fn should_retry_internal_action_item_final_answer(
    final_answer: &str,
    tool_call_count: usize,
) -> bool {
    if tool_call_count > 0 {
        return false;
    }

    let normalized = normalize_action_item_text(final_answer);
    if normalized.is_empty() {
        return false;
    }

    normalized.starts_with("next single step")
        || normalized.starts_with("single step")
        || normalized.starts_with("next step")
        || normalized.starts_with("check whether ")
        || normalized.starts_with("inspect ")
        || normalized.starts_with("confirm ")
        || normalized.starts_with("find the ")
        || normalized.starts_with("look for ")
}

fn should_retry_incomplete_progress_final_answer(
    summary: &str,
    final_answer: &str,
    execution_mode: &str,
    worker: &WorkerSummary,
    step_count: usize,
    tool_call_count: usize,
) -> bool {
    if execution_mode == "plan" || !has_remaining_worker_budget(worker, step_count, tool_call_count)
    {
        return false;
    }

    let text = normalize_action_item_text(&format!("{}\n{}", summary, final_answer));
    if text.is_empty() || contains_blocked_or_waiting_language(&text) {
        return false;
    }

    contains_incomplete_work_language(&text)
}

fn has_remaining_worker_budget(
    worker: &WorkerSummary,
    step_count: usize,
    tool_call_count: usize,
) -> bool {
    let has_step_budget = worker.max_steps == 0 || step_count.saturating_add(1) < worker.max_steps;
    let has_action_budget =
        worker.max_tool_calls == 0 || tool_call_count.saturating_add(1) < worker.max_tool_calls;
    has_step_budget && has_action_budget
}

