fn mcp_tool_capabilities(state: &AppState) -> Vec<ToolCapabilityGrantRecord> {
    let Ok(servers) = state.store.list_mcp_servers() else {
        return Vec::new();
    };
    let enabled_servers = servers
        .into_iter()
        .filter(|server| server.enabled)
        .map(|server| server.id)
        .collect::<BTreeSet<_>>();
    if enabled_servers.is_empty() {
        return Vec::new();
    }

    state
        .store
        .list_mcp_tools()
        .unwrap_or_default()
        .into_iter()
        .filter(|tool| enabled_servers.contains(&tool.server_id))
        .map(|tool| ToolCapabilityGrantRecord {
            tool_id: tool.id,
            summary: if tool.description.trim().is_empty() {
                format!("Invoke MCP tool {} via Nucleus.", tool.name)
            } else {
                tool.description
            },
            approval_mode: "explicit".to_string(),
            risk_level: "medium".to_string(),
            side_effect_level: "external".to_string(),
            timeout_secs: 30,
            max_output_bytes: 32_768,
            supports_streaming: false,
            concurrency_group: "mcp".to_string(),
            scope_kind: "mcp".to_string(),
        })
        .collect()
}

fn worker_system_prompt(worker: &WorkerSummary) -> String {
    worker_system_prompt_with_mode(worker, "act")
}

fn worker_system_prompt_with_mode(worker: &WorkerSummary, execution_mode: &str) -> String {
    worker_system_prompt_with_context(worker, execution_mode, false)
}

fn worker_system_prompt_with_context(
    worker: &WorkerSummary,
    execution_mode: &str,
    low_context_turn: bool,
) -> String {
    if execution_mode == "plan" {
        return format!(
            "Respond to the user as the Utility Nucleus {} worker.\n\
Nucleus worker action JSON contract: return one valid Nucleus worker action JSON object.\n\
Plan mode is enabled for this session.\n\
Allowed response shape:\n\
{{\"kind\":\"final_answer\",\"thoughts\":\"brief reason this can be answered without tools\",\"summary\":\"what the plan covers\",\"final_answer\":\"concise user-facing plan\"}}\n\
Rules:\n\
- Think briefly in thoughts before choosing the final_answer.\n\
- Do not call tools.\n\
- Do not spawn child workers.\n\
- Do not run commands, inspect files, edit files, or assume action results.\n\
- You may reason from the user's prompt and existing visible context only.\n\
- The visible chat will receive final_answer.\n\
- Do not wrap JSON in markdown fences.\n\
Available tools: disabled in Plan mode.\n\
Worker lane: {}\n\
Working directory: {}\n",
            worker.lane, worker.lane, worker.working_dir
        );
    }

    let is_root_worker = worker.parent_worker_id.is_none();
    if low_context_turn && is_root_worker {
        let action_shapes = "{\"kind\":\"final_answer\",\"thoughts\":\"brief reason the prompt is already answerable\",\"summary\":\"why the response is complete\",\"final_answer\":\"clean user-facing answer\",\"browser_verification\":{\"status\":\"passed|failed|not_performed|unavailable\",\"summary\":\"concise Browser verification result\",\"artifact_ids\":[\"artifact-id\"]}}\n\
{\"kind\":\"tool_call\",\"thoughts\":\"brief reason this needs local evidence\",\"summary\":\"inspect the active project or workspace\",\"tool\":\"project.inspect\",\"args\":{}}\n\
{\"kind\":\"tool_call\",\"summary\":\"list likely workspace directories\",\"tool\":\"fs.list\",\"args\":{\"path\":\".\",\"recursive\":false,\"limit\":100}}\n\
{\"kind\":\"tool_call\",\"summary\":\"fetch inline PR review threads\",\"tool\":\"github.pr_review_threads\",\"args\":{\"pr_number\":123}}\n\
{\"kind\":\"tool_call\",\"summary\":\"fetch direct PR lifecycle state\",\"tool\":\"github.pr_state\",\"args\":{\"pr_number\":123}}\n\
{\"kind\":\"tool_call\",\"summary\":\"run a focused local command\",\"tool\":\"command.run\",\"args\":{\"command\":\"sh\",\"args\":[\"-lc\",\"pwd\"],\"cwd\":\".\",\"timeout_secs\":20}}\n\
{\"kind\":\"tool_call\",\"summary\":\"verify the UI in Browser\",\"tool\":\"browser.navigate\",\"args\":{\"url\":\"http://127.0.0.1:5299\"}}\n\
{\"kind\":\"tool_call\",\"summary\":\"read Browser refs\",\"tool\":\"browser.snapshot\",\"args\":{}}\n\
{\"kind\":\"tool_call\",\"summary\":\"click a Browser control by ref\",\"tool\":\"browser.click\",\"args\":{\"target_ref\":\"ref-1\"}}\n\
{\"kind\":\"final_answer\",\"summary\":\"why the work is done\",\"final_answer\":\"clean user-facing answer\"}";
        let action_shapes = if worker_has_tool_capability(worker, "browser.navigate") {
            action_shapes.to_string()
        } else {
            action_shapes
                .lines()
                .filter(|line| !line.contains("\"tool\":\"browser."))
                .collect::<Vec<_>>()
                .join("\n")
        };
        let tool_help = worker
            .capabilities
            .iter()
            .filter(|capability| low_context_prompt_tool_visible(&capability.tool_id))
            .map(|capability| {
                format!(
                    "- {}: {} (approval={}, risk={})",
                    capability.tool_id,
                    capability.summary,
                    capability.approval_mode,
                    capability.risk_level
                )
            })
            .collect::<Vec<_>>()
            .join("\n");

        return format!(
            "Respond to the user as the Utility Nucleus {} worker. This is a low-context turn; prefer a concise final_answer unless evidence or action is truly needed.\n\
Nucleus worker action JSON contract: return one valid Nucleus worker action JSON object.\n\
Allowed response shapes:\n\
{}\n\
Rules:\n\
- Think briefly in the thoughts field first, then choose the action.\n\
- If the user's prompt is conversational or already answerable from visible context, answer directly with final_answer.\n\
- Use tools only when they materially improve the answer, and choose the smallest useful action.\n\
- Never invent tool output.\n\
- Stay inside the granted repo scope.\n\
- For UI or visual changes, use Browser tools when Browser verification is required and available.\n\
- For UI-renderable work, include browser_verification in final_answer with status passed, failed, not_performed, or unavailable. Typecheck/build success alone is not rendered-UI verification.\n\
- For PR review or lifecycle claims, fetch thread-aware review data with github.pr_review_threads or direct PR state with github.pr_state before making the claim.\n\
- The visible chat will only receive final_answer, not your intermediate reasoning.\n\
- Use final_answer as the terminal action when the user is answered, the requested task is complete and validated, or you are genuinely blocked.\n\
- Do not use provider-native tool wrappers such as tool_call/tool_name/shell; use the exact Nucleus JSON shapes above.\n\
- Do not wrap JSON in markdown fences.\n\
Available tools:\n\
{}\n\
Worker lane: {}\n\
Working directory: {}\n",
            worker.lane, action_shapes, tool_help, worker.lane, worker.working_dir
        );
    }

    let action_shapes = if is_root_worker {
        "{\"kind\":\"spawn_child_jobs\",\"summary\":\"delegate implementation or repo research to main\",\"jobs\":[{\"title\":\"Main work owner\",\"prompt\":\"Scope: handle the requested implementation, debugging, broad repo research, validation, and concise report back to the root. Expected output: changes and validation when requested, or evidence-backed findings for read-only work. Join criteria: root can complete the user-facing answer from the child report without repeating broad exploration.\",\"task_class\":\"local_project\"}]}\n\
{\"kind\":\"spawn_child_jobs\",\"summary\":\"run a cheap deterministic check on utility\",\"jobs\":[{\"title\":\"focused check\",\"prompt\":\"precise bounded check and expected report\",\"task_class\":\"local_project\",\"route_id\":\"utility\"}]}\n\
{\"kind\":\"final_answer\",\"thoughts\":\"brief reason the prompt is already answerable\",\"summary\":\"why the response is complete\",\"final_answer\":\"clean user-facing answer\",\"browser_verification\":{\"status\":\"passed|failed|not_performed|unavailable\",\"summary\":\"concise Browser verification result\",\"artifact_ids\":[\"artifact-id\"]}}\n\
{\"kind\":\"tool_call\",\"thoughts\":\"brief reason this needs targeted root triage or validation\",\"summary\":\"inspect the active project\",\"tool\":\"project.inspect\",\"args\":{}}\n\
{\"kind\":\"tool_call\",\"summary\":\"list likely project directories\",\"tool\":\"fs.list\",\"args\":{\"path\":\".\",\"recursive\":false,\"limit\":100}}\n\
{\"kind\":\"tool_call\",\"summary\":\"fetch inline PR review threads\",\"tool\":\"github.pr_review_threads\",\"args\":{\"pr_number\":123}}\n\
{\"kind\":\"tool_call\",\"summary\":\"fetch direct PR lifecycle state\",\"tool\":\"github.pr_state\",\"args\":{\"pr_number\":123}}\n\
{\"kind\":\"tool_call\",\"summary\":\"check running dev processes\",\"tool\":\"command.run\",\"args\":{\"command\":\"sh\",\"args\":[\"-lc\",\"ps -ef | grep -iE 'stfr|vite|next|webpack|dev server' | grep -v grep\"],\"cwd\":\".\",\"timeout_secs\":20}}\n\
{\"kind\":\"tool_call\",\"summary\":\"run a Python snippet through Nucleus runtime discovery\",\"tool\":\"python.run\",\"args\":{\"script\":\"print('hello')\",\"cwd\":\".\",\"timeout_secs\":20}}\n\
{\"kind\":\"tool_call\",\"summary\":\"verify the UI in Browser\",\"tool\":\"browser.navigate\",\"args\":{\"url\":\"http://127.0.0.1:5299\"}}\n\
{\"kind\":\"tool_call\",\"summary\":\"read Browser refs\",\"tool\":\"browser.snapshot\",\"args\":{}}\n\
{\"kind\":\"tool_call\",\"summary\":\"click a Browser control by ref\",\"tool\":\"browser.click\",\"args\":{\"target_ref\":\"ref-1\"}}\n\
{\"kind\":\"progress_update\",\"summary\":\"durable checkpoint, not done\",\"detail\":\"completed evidence and exact continuation point\"}\n\
{\"kind\":\"wait\",\"summary\":\"park until an external condition is ready\",\"until\":{\"kind\":\"delay_seconds\",\"delay_seconds\":60},\"max_wait_seconds\":1800,\"wake_note\":\"optional wake-up context\"}\n\
{\"kind\":\"wait\",\"summary\":\"park until memory classification finishes\",\"until\":{\"kind\":\"audit_event\",\"event_kind\":\"memory.classifier.completed\",\"target_pattern\":\"session:\",\"status\":\"success\"},\"max_wait_seconds\":1800}\n\
{\"kind\":\"final_answer\",\"summary\":\"why the work is done\",\"final_answer\":\"clean user-facing answer\"}"
    } else {
        "{\"kind\":\"final_answer\",\"thoughts\":\"brief reason the prompt is already answerable\",\"summary\":\"why the response is complete\",\"final_answer\":\"clean user-facing answer\"}\n\
{\"kind\":\"tool_call\",\"thoughts\":\"brief reason this needs project evidence\",\"summary\":\"inspect the active project\",\"tool\":\"project.inspect\",\"args\":{}}\n\
{\"kind\":\"tool_call\",\"summary\":\"list likely project directories\",\"tool\":\"fs.list\",\"args\":{\"path\":\".\",\"recursive\":false,\"limit\":100}}\n\
{\"kind\":\"tool_call\",\"summary\":\"fetch inline PR review threads\",\"tool\":\"github.pr_review_threads\",\"args\":{\"pr_number\":123}}\n\
{\"kind\":\"tool_call\",\"summary\":\"fetch direct PR lifecycle state\",\"tool\":\"github.pr_state\",\"args\":{\"pr_number\":123}}\n\
{\"kind\":\"progress_update\",\"summary\":\"durable checkpoint, not done\",\"detail\":\"completed evidence and exact continuation point\"}\n\
{\"kind\":\"wait\",\"summary\":\"park until an external condition is ready\",\"until\":{\"kind\":\"delay_seconds\",\"delay_seconds\":60},\"max_wait_seconds\":1800,\"wake_note\":\"optional wake-up context\"}\n\
{\"kind\":\"wait\",\"summary\":\"park until a child report exists\",\"until\":{\"kind\":\"artifact_kind\",\"job_id\":\"job-id\",\"artifact_kind\":\"child-report\"},\"max_wait_seconds\":1800}\n\
{\"kind\":\"final_answer\",\"summary\":\"why the work is done\",\"final_answer\":\"clean user-facing answer\"}"
    };
    let action_shapes = if is_root_worker && !worker_has_tool_capability(worker, "browser.navigate")
    {
        action_shapes
            .lines()
            .filter(|line| !line.contains("\"tool\":\"browser."))
            .collect::<Vec<_>>()
            .join("\n")
    } else {
        action_shapes.to_string()
    };
    let tool_help = worker
        .capabilities
        .iter()
        .map(|capability| {
            format!(
                "- {}: {} (approval={}, risk={})",
                capability.tool_id,
                capability.summary,
                capability.approval_mode,
                capability.risk_level
            )
        })
        .collect::<Vec<_>>()
        .join("\n");
    let child_job_rules = if is_root_worker {
        "- You are the root Utility Worker: a lightweight coordinator that gates budgets, delegates bounded work, and joins child results.\n\
- You do not do broad repository exploration, heavy implementation, or deep reasoning yourself when the work can be bounded for a child worker.\n\
- Use spawn_child_jobs for heavy implementation, multi-step investigation, broad search, repo research, or work that benefits from bounded delegation.\n\
- For implementation, debugging, broad repo research, multi-file investigation, issue archaeology, testing, or PR work, spawn one main-lane child with no route_id when the main route is usable; if a required main-lane child is concretely unavailable, state that blocker instead of silently doing the broad work yourself.\n\
- Use route_id=\"utility\" only for cheap deterministic checks with small expected answers. Do not use utility children for broad repo research, issue archaeology, multi-file inspection, or implementation planning.\n\
- Only root workers may fan out child jobs. Main-lane children inherit your granted tool set and bounded write scope; utility children are for read-only checks.\n\
- When spawning write-capable sibling children, give each child a dedicated working_dir inside your scope so its write root and lock are narrowed to that path.\n\
- Use at most 5 child jobs in a single spawn_child_jobs action.\n\
- Multi-child main-lane fan-out must use distinct existing working_dir values from visible context or targeted triage; if the root cannot identify those directories, that is a concrete reason to do one targeted triage action before spawning.\n\
- When full-repo or multi-file scope is needed, prefer one main-lane child unless the task is only a tiny deterministic check.\n\
- After child results satisfy the request, synthesize from their reports directly. Do not repeat the children's exploration; use direct tools only for a specific identified gap.\n\
- Failure-case few-shot: if the user asks \"thoroughly investigate this codebase across many files\", the correct root response is one spawn_child_jobs action with one main-lane child:\n\
{\"kind\":\"spawn_child_jobs\",\"summary\":\"thorough codebase investigation delegates repo research to main\",\"jobs\":[{\"title\":\"Main investigation owner\",\"prompt\":\"Scope: inspect relevant files, tests, and docs across the codebase without making edits unless the original request asks for changes. Expected output: evidence-backed findings, key paths, uncertainties, and recommended validation. Join criteria: root can answer from the child report without repeating broad exploration.\",\"task_class\":\"local_project\"}]}\n"
    } else {
        ""
    };

    let root_action_rules = if is_root_worker {
        "- Mandatory delegation rule: for broad investigation, multi-file analysis, implementation, debugging, deep reasoning, or anything likely to need more than about 1-2 evidence/tool calls, issue spawn_child_jobs first unless there is a concrete reason delegation is impossible; if delegation is impossible, state that reason.\n\
- Trivial single-step asks, such as reading one named file or answering from visible context, may be answered directly or with one targeted direct tool.\n\
- Direct root tools are for triage, targeted validation, and final join gaps; they are not for broad repository exploration or heavy reasoning.\n"
    } else {
        "- Choose the smallest useful next action when the request needs action, external state, or local evidence.\n\
- Use tools only when they materially improve the answer.\n"
    };

    let root_orchestration_note = if is_root_worker {
        "Root-only orchestration:\n\
- spawn_child_jobs is a primary root operation for bounded fan-out to child workers. Prefer it before direct tools whenever the request is broad, multi-step, or likely to exceed about 1-2 evidence/tool calls.\n"
    } else {
        ""
    };

    let worker_intro = if is_root_worker {
        "Respond to the user as the root Utility Worker. You are a lightweight coordinator for this Nucleus session: coordinate, gate budgets, delegate bounded work, and join results. Mandatory delegation rule: broad investigation, multi-file analysis, implementation, debugging, deep reasoning, or anything likely to need more than about 1-2 evidence/tool calls must start with spawn_child_jobs unless delegation is concretely impossible. Direct tools are for triage, targeted validation, and final join gaps, not broad exploration."
            .to_string()
    } else {
        format!(
            "Respond to the user as a Nucleus {} child worker. Execute the bounded task from your parent and report results clearly.",
            worker.lane
        )
    };

    format!(
        "{}\n\
Nucleus worker action JSON contract: return one valid Nucleus worker action JSON object.\n\
Allowed response shapes:\n\
{}\n\
Rules:\n\
- Think briefly in the thoughts field first, then choose the action.\n\
- If the user's prompt is conversational or already answerable from visible context, answer directly with final_answer.\n\
{}\n\
- Never invent tool output.\n\
- Stay inside the granted repo scope.\n\
{}\
- For UI or visual changes, strongly prefer Browser verification before final_answer when Browser tools are available: navigate to the matched local app, inspect refs/snapshot or screenshot, interact as needed, and cite artifact/result evidence.\n\
- For UI-renderable work, include browser_verification in final_answer with status passed, failed, not_performed, or unavailable. Typecheck/build success alone is not rendered-UI verification.\n\
- Prefer daemon-generated Browser refs for browser.click/browser.type/browser.fill/browser.scroll/browser.press/browser.submit. Do not invent selectors when a ref is available.\n\
- The visible chat will only receive final_answer, not your intermediate reasoning.\n\
- progress_update records a non-terminal checkpoint for Nucleus; it does not complete the job.\n\
- wait parks the worker until delay_seconds, absolute_unix, audit_event, child_jobs_completed, or artifact_kind is satisfied. It does not spend step/action budget but still spends wall-clock budget.\n\
- Do not put plans, next-step instructions, progress updates, partial completion notes, or descriptions of future actions in final_answer.\n\
- If the requested work needs more evidence or action and you are not blocked or out of budget, continue with the appropriate action instead of returning final_answer.\n\
- For PR feedback, latest review, requested changes, Codex review, or unresolved comment tasks, do not rely on flat gh pr view comments alone. Fetch thread-aware inline review data with github.pr_review_threads before saying there is no actionable feedback.\n\
- For PR lifecycle claims like merged, open, closed, ready, mergeable, or approved, fetch direct GitHub PR state with github.pr_state. Local git state can supplement, but it is never enough to say a PR is already merged or that nothing is left to merge. Only say that when direct PR state is MERGED or mergedAt is non-empty. If PR identity is unclear, resolve it from the session branch or ask a bounded follow-up.\n\
- If a user challenges or repeats a prior clean/no-action answer, treat it as a grounding failure signal and use a deeper or different evidence path before repeating the conclusion.\n\
- Treat zero matched tests as no tests matched, not validation success.\n\
- When posting GitHub comments, use github.comment or a body file/stdin path. Do not put comment bodies with backticks or shell metacharacters inside sh -lc strings.\n\
- Use python.run for Python snippets instead of hard-coding python or python3 in command.run. For simple edits, prefer fs.apply_patch or fs.write_text over script-generated edits.\n\
- Use final_answer as the terminal action when the user is answered, the requested task is complete and validated, or you are genuinely blocked.\n\
- Do not use provider-native tool wrappers such as tool_call/tool_name/shell; use the exact Nucleus JSON shapes above.\n\
- Do not wrap JSON in markdown fences.\n\
Available tools:\n{}\n\
{}\n\
{}\n\
Worker lane: {}\n\
Working directory: {}\n",
        worker_intro,
        action_shapes,
        root_action_rules,
        child_job_rules,
        tool_help,
        root_orchestration_note,
        python_runtime_prompt_status(
            Path::new(&worker.working_dir),
            Some(Path::new(&worker.working_dir)),
        ),
        worker.lane,
        worker.working_dir
    )
}

