    #[test]
    fn agent_runtime_transfers_write_locks_between_tool_and_command_owners() {
        let runtime = AgentRuntime::default();

        assert!(
            runtime
                .try_claim_write_lock(
                    "tool-call",
                    "job-a",
                    "worker-a",
                    &[String::from("/tmp/repo")],
                    "fs.write_text: update file",
                )
                .expect("first claim should succeed")
                .is_none()
        );

        let conflict = runtime
            .try_claim_write_lock(
                "other-owner",
                "job-b",
                "worker-b",
                &[String::from("/tmp/repo/src")],
                "command.run: cargo test",
            )
            .expect("conflict check should succeed")
            .expect("second owner should conflict");
        assert_eq!(conflict.job_id, "job-a");

        runtime
            .transfer_write_lock("tool-call", "command-session")
            .expect("lock transfer should succeed");

        let conflict = runtime
            .try_claim_write_lock(
                "other-owner",
                "job-b",
                "worker-b",
                &[String::from("/tmp/repo/src")],
                "command.run: cargo test",
            )
            .expect("conflict check should succeed")
            .expect("transferred owner should still conflict");
        assert_eq!(conflict.owner_id, "command-session");

        runtime.release_write_lock("command-session");

        assert!(
            runtime
                .try_claim_write_lock(
                    "other-owner",
                    "job-b",
                    "worker-b",
                    &[String::from("/tmp/repo/src")],
                    "command.run: cargo test",
                )
                .expect("claim after release should succeed")
                .is_none()
        );
    }

    #[test]
    fn worker_prompt_limits_child_job_fanout_to_root_workers() {
        let root_worker = WorkerSummary {
            id: "root".to_string(),
            job_id: "job".to_string(),
            parent_worker_id: None,
            title: "Root worker".to_string(),
            lane: "utility".to_string(),
            state: "queued".to_string(),
            provider: "test".to_string(),
            model: "test".to_string(),
            route_id: String::new(),
            route_title: String::new(),
            provider_base_url: String::new(),
            provider_api_key: String::new(),
            provider_session_id: String::new(),
            working_dir: "/tmp".to_string(),
            read_roots: vec!["/tmp".to_string()],
            write_roots: vec!["/tmp".to_string()],
            max_steps: 10,
            max_tool_calls: 10,
            max_wall_clock_secs: 30,
            step_count: 0,
            tool_call_count: 0,
            wait_until_json: None,
            wait_started_at: None,
            last_error: String::new(),
            user_error: None,
            capabilities: Vec::new(),
            last_reasoning: String::new(),
            last_reasoning_at: None,
            token_usage_known: false,
            prompt_tokens: 0,
            completion_tokens: 0,
            cached_tokens: 0,
            cost_usd_estimate: None,
            created_at: 0,
            updated_at: 0,
        };
        let child_worker = WorkerSummary {
            id: "child".to_string(),
            parent_worker_id: Some("root".to_string()),
            ..root_worker.clone()
        };

        let root_prompt = worker_system_prompt(&root_worker);
        let child_prompt = worker_system_prompt(&child_worker);

        assert!(root_prompt.contains("spawn_child_jobs"));
        assert!(!child_prompt.contains("spawn_child_jobs"));
        assert!(root_prompt.contains("Main-lane children inherit your granted tool set"));
        assert!(!root_prompt.contains("child jobs must stay read-only"));
        assert!(root_prompt.contains("{\"kind\":\"final_answer\""));
        assert!(root_prompt.contains("Nucleus worker action JSON contract"));
        assert!(root_prompt.contains("Think briefly in the thoughts field first"));
        assert!(root_prompt.contains("already answerable from visible context"));
        let root_python_runtime_section = root_prompt
            .split("Python runtime:")
            .nth(1)
            .expect("root prompt should include Python runtime status");
        assert!(root_python_runtime_section.contains("\nWorker lane:"));
        assert!(!root_prompt.contains("and nothing else"));
        assert!(
            root_prompt.find("{\"kind\":\"spawn_child_jobs\"")
                < root_prompt.find("{\"kind\":\"tool_call\""),
            "root worker prompt should present spawn_child_jobs before direct tool_call examples"
        );
        assert!(
            root_prompt.contains("Mandatory delegation rule: for broad investigation"),
            "root prompt should make delegation mandatory for broad work"
        );
        assert!(
            root_prompt.contains("lightweight coordinator"),
            "root prompt should frame the root as a lightweight coordinator"
        );
        assert!(
            root_prompt.contains(
                "Direct root tools are for triage, targeted validation, and final join gaps"
            ),
            "root prompt should narrow direct root tools to triage, validation, and join gaps"
        );
        assert!(
            root_prompt.contains("Root-only orchestration"),
            "root prompt should surface spawn_child_jobs near available tools"
        );
        assert!(
            root_prompt.contains("thoroughly investigate this codebase across many files"),
            "root prompt should include the broad-investigation few-shot"
        );
        assert!(
            root_prompt.contains("one spawn_child_jobs action with one main-lane child"),
            "root prompt few-shot should require one bounded main-lane child"
        );
        assert!(
            root_prompt.contains("delegate implementation or repo research to main")
                && root_prompt.contains("Main work owner")
                && root_prompt.contains("Main investigation owner")
                && root_prompt.contains("run a cheap deterministic check on utility")
                && root_prompt.contains("\"route_id\":\"utility\""),
            "root prompt should show main-first repo research with utility only for tiny checks"
        );
        assert!(
            !root_prompt.contains("broad read-only investigation delegates focused utility checks"),
            "broad-investigation few-shot should not teach utility research fanout"
        );
        assert!(
            root_prompt.contains(
                "spawn one main-lane child with no route_id when the main route is usable"
            ),
            "root prompt should gate main-lane child guidance on route usability"
        );
        assert!(
            root_prompt
                .contains("Multi-child main-lane fan-out must use distinct existing working_dir"),
            "root prompt should explain the existing-directory constraint for multi-main fan-out"
        );
        assert!(
            root_prompt.contains("Do not repeat the children's exploration"),
            "root prompt should strengthen the join contract"
        );
        assert!(
            !root_prompt.contains("Use tools only when the task actually needs them"),
            "root prompt should not keep the old self-service tool framing"
        );
        assert!(
            !root_prompt
                .contains("Choose the smallest useful next action when the request needs action"),
            "root prompt should not use the generic smallest-action rule"
        );
        assert!(
            !root_prompt.contains("{{\"kind\""),
            "worker prompt must show valid single-object JSON examples"
        );
        assert!(
            root_prompt.contains("Do not put plans, next-step instructions"),
            "worker prompt should prevent internal plans from becoming visible answers"
        );
        assert!(root_prompt.contains("{\"kind\":\"progress_update\""));
        assert!(root_prompt.contains("progress_update records a non-terminal checkpoint"));
        assert!(
            root_prompt.contains("\"tool\":\"command.run\""),
            "worker prompt should include concrete command.run action shape"
        );
        assert!(
            root_prompt.contains("Do not use provider-native tool wrappers"),
            "worker prompt should reject provider-native tool-call shapes"
        );
    }

