    #[test]
    fn publication_browser_status_reconciliation_preserves_terminal_fallback() {
        let mut job = test_publication_job_summary("publication-browser-terminal");
        job.browser_verification_status = "not_performed".to_string();
        let mut patch = PublicationOutcomePatch {
            publication_requested: Some(true),
            browser_verification_status: Some("pending".to_string()),
            ..PublicationOutcomePatch::default()
        };

        reconcile_publication_browser_status_with_completion(&job, &mut patch);

        assert_eq!(
            patch.browser_verification_status.as_deref(),
            Some("not_performed")
        );

        patch.browser_verification_status = Some("unavailable".to_string());
        reconcile_publication_browser_status_with_completion(&job, &mut patch);
        assert_eq!(
            patch.browser_verification_status.as_deref(),
            Some("unavailable")
        );

        job.browser_verification_status = "passed".to_string();
        reconcile_publication_browser_status_with_completion(&job, &mut patch);
        assert_eq!(patch.browser_verification_status.as_deref(), Some("passed"));
    }

    #[test]
    fn projected_completion_gates_block_non_publication_browser_and_cleanup_failures() {
        let mut browser_job = test_publication_job_summary("browser-gated");
        browser_job.publication_requested = false;
        browser_job.publication_status = "not_requested".to_string();
        browser_job.pr_url = String::new();
        browser_job.browser_verification_required = true;
        browser_job.browser_verification_status = "failed".to_string();
        browser_job.validation_status = "not_performed".to_string();
        browser_job.cleanup_status = "clean".to_string();

        assert!(projected_completion_gates_blocked(
            &browser_job,
            &PublicationOutcomePatch::default()
        ));

        let mut cleanup_job = browser_job.clone();
        cleanup_job.browser_verification_required = false;
        cleanup_job.browser_verification_status = "not_required".to_string();
        cleanup_job.cleanup_status = "cleanup_required".to_string();
        cleanup_job.cleanup_paths = vec![".tmp-playwright".to_string()];

        assert!(projected_completion_gates_blocked(
            &cleanup_job,
            &PublicationOutcomePatch::default()
        ));
    }

    #[test]
    fn projected_completion_gates_block_unmet_task_class_evidence() {
        let cases = [
            (
                "research",
                vec![
                    "fresh_sources:https://example.test/source".to_string(),
                    "source_quality:primary source".to_string(),
                    "contradictions:checked alternate sources".to_string(),
                ],
            ),
            (
                "automation",
                vec!["schedule_state:task created".to_string()],
            ),
            (
                "local_project",
                vec!["validation:cargo test passed".to_string()],
            ),
            (
                "deployment",
                vec![
                    "deployment_status:deploy command passed".to_string(),
                    "health:post-deploy endpoint returned 200".to_string(),
                ],
            ),
            (
                "memory_session",
                vec![
                    "target_scope:session".to_string(),
                    "operation_result:memory write receipt".to_string(),
                ],
            ),
            (
                "process_server",
                vec![
                    "process_state:restart completed".to_string(),
                    "port_state:listener observed".to_string(),
                ],
            ),
        ];

        for (task_class, evidence) in cases {
            let mut job = test_publication_job_summary(task_class);
            job.publication_requested = false;
            job.publication_status = "not_requested".to_string();
            job.browser_verification_required = false;
            job.browser_verification_status = "not_required".to_string();
            job.cleanup_status = "unknown".to_string();
            job.task_class = Some(task_class.to_string());
            job.task_evidence = Vec::new();

            let blocker =
                projected_completion_gate_blocker(&job, &PublicationOutcomePatch::default())
                    .expect("missing task evidence should block");
            assert!(
                contradiction_checked_final_answer(
                    "Done.",
                    "blocked",
                    &PublicationOutcomePatch::default(),
                    Some(&blocker)
                )
                .starts_with("Blocked:"),
                "{task_class}"
            );

            job.task_evidence = evidence;
            assert!(!projected_completion_gates_blocked(
                &job,
                &PublicationOutcomePatch::default()
            ));
        }

        let mut ungated = test_publication_job_summary("ungated-task");
        ungated.publication_requested = false;
        ungated.publication_status = "not_requested".to_string();
        ungated.browser_verification_required = false;
        ungated.browser_verification_status = "not_required".to_string();
        ungated.cleanup_status = "unknown".to_string();
        ungated.task_class = None;

        assert!(!projected_completion_gates_blocked(
            &ungated,
            &PublicationOutcomePatch::default()
        ));
    }

