        assert!(started.elapsed() > Duration::from_secs(15));
        assert!(matches!(
            response.action,
            WorkerAction::FinalAnswer { final_answer, .. } if final_answer == "Done after streaming."
        ));
        assert_eq!(request_count.load(Ordering::SeqCst), 1);
