    async fn wait_for_latest_job_state(
        state: &AppState,
        session_id: &str,
        expected_state: &str,
    ) -> JobDetail {
        for _ in 0..200 {
            let jobs = state
                .store
                .list_jobs_for_session(session_id)
                .expect("session jobs should load while polling");
            if let Some(job) = jobs.first() {
                let detail = state.store.get_job(&job.id).expect("job should load");
                if detail.job.state == expected_state {
                    return detail;
                }
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }

        panic!("latest session job did not reach state '{expected_state}'");
    }

    async fn wait_for_job_state(state: &AppState, job_id: &str, expected_state: &str) -> JobDetail {
        let mut last_state = String::new();
        let mut last_error = String::new();
        for _ in 0..500 {
            let detail = state.store.get_job(job_id).expect("job should load");
            if detail.job.state == expected_state {
                return detail;
            }
            last_state = detail.job.state.clone();
            last_error = detail.job.last_error.clone();
            tokio::time::sleep(Duration::from_millis(10)).await;
        }

        panic!(
            "job '{job_id}' did not reach state '{expected_state}' (last state: '{last_state}', last error: '{last_error}')"
        );
    }

    async fn wait_for_child_count(
        state: &AppState,
        session_id: &str,
        expected_count: usize,
    ) -> JobDetail {
        for _ in 0..500 {
            let detail = latest_job_detail(state, session_id);
            if detail.child_jobs.len() == expected_count {
                return detail;
            }
            tokio::time::sleep(Duration::from_millis(10)).await;
        }

        panic!("latest session job did not record {expected_count} child jobs");
    }

    fn latest_job_detail(state: &AppState, session_id: &str) -> JobDetail {
        let jobs = state
            .store
            .list_jobs_for_session(session_id)
            .expect("session jobs should load");
        let job = jobs.first().expect("session should have a job");
        state
            .store
            .get_job(&job.id)
            .expect("job detail should load")
    }

    fn spawn_child_jobs_action_json(
        count: usize,
        failing_index: Option<usize>,
        prompt_prefix: &str,
    ) -> String {
        let jobs = (0..count)
            .map(|index| {
                let prompt = if Some(index) == failing_index {
                    format!("{prompt_prefix}-{index}: child-fail")
                } else {
                    format!("{prompt_prefix}-{index}: child-success")
                };
                json!({
                    "title": format!("Child {index}"),
                    "prompt": prompt,
                    "working_dir": format!("child-{index}"),
                })
            })
            .collect::<Vec<_>>();
        json!({
            "kind": "spawn_child_jobs",
            "summary": format!("fan out to {count} child jobs"),
            "jobs": jobs,
        })
        .to_string()
    }

    fn create_child_workdirs(workspace_root: &Path, count: usize) {
        for index in 0..count {
            fs::create_dir_all(workspace_root.join(format!("child-{index}")))
                .expect("child workdir should exist");
        }
    }

    fn install_fake_rg_command() {
        static FAKE_RG: OnceLock<PathBuf> = OnceLock::new();
        let path = FAKE_RG.get_or_init(|| {
            let path = env::temp_dir().join("nucleus-test-fake-rg");
            fs::write(
                &path,
                "#!/usr/bin/env sh\nfor arg in \"$@\"; do\n  if [ \"$arg\" = \"[\" ]; then\n    echo \"invalid glob\" >&2\n    exit 2\n  fi\ndone\nexit 1\n",
            )
            .expect("fake rg should write");
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                fs::set_permissions(&path, fs::Permissions::from_mode(0o755))
                    .expect("fake rg should be executable");
            }
            path
        });
        set_test_command_override("rg", path.clone());
    }

